  ('h15a_primitiveren', 'h15a_primitief', $h15sql$Primitiveer $f(x) = \dfrac{2x + 5}{x + 2}$.$h15sql$, $h15sql$2x + ln(abs(x + 2)) + c$h15sql$, $h15sql$F(x) = 2x + \ln|x + 2| + c$h15sql$, 1, 2, ARRAY[]::text[]),
  ('h15a_primitiveren', 'h15a_primitief', $h15sql$Primitiveer $f(x) = \dfrac{3x - 1}{x + 1}$.$h15sql$, $h15sql$3x - 4ln(abs(x + 1)) + c$h15sql$, $h15sql$F(x) = 3x - 4\ln|x + 1| + c$h15sql$, 1, 3, ARRAY[]::text[]),
  ('h15a_primitiveren', 'h15a_primitief', $h15sql$Primitiveer $f(x) = \dfrac{4x + 1}{2x + 1}$.$h15sql$, $h15sql$2x - (1/2)ln(abs(2x + 1)) + c$h15sql$, $h15sql$F(x) = 2x - \tfrac{1}{2}\ln|2x + 1| + c$h15sql$, 2, 4, ARRAY[$h15sql$2x - 0,5ln(abs(2x + 1)) + c$h15sql$]::text[]),
  ('h15a_primitiveren', 'h15a_primitief', $h15sql$Primitiveer $g(x) = \dfrac{x - 4}{2x + 3}$.$h15sql$, $h15sql$(1/2)x - (11/4)ln(abs(2x + 3)) + c$h15sql$, $h15sql$G(x) = \tfrac{1}{2}x - \tfrac{11}{4}\ln|2x + 3| + c$h15sql$, 2, 5, ARRAY[]::text[]),
  ('h15a_primitiveren', 'h15a_primitief', $h15sql$Primitiveer $f(x) = \dfrac{5 - 2x}{x + 3}$.$h15sql$, $h15sql$-2x + 11ln(abs(x + 3)) + c$h15sql$, $h15sql$F(x) = -2x + 11\ln|x + 3| + c$h15sql$, 2, 6, ARRAY[]::text[]),
  ('h15a_primitiveren', 'h15a_primitief', $h15sql$Primitiveer $f(x) = \dfrac{6x - 1}{3x + 2}$.$h15sql$, $h15sql$2x - (5/3)ln(abs(3x + 2)) + c$h15sql$, $h15sql$F(x) = 2x - \tfrac{5}{3}\ln|3x + 2| + c$h15sql$, 3, 7, ARRAY[]::text[]),
  ('h15a_primitiveren', 'h15a_primitief', $h15sql$Primitiveer $h(x) = \dfrac{3x + 5}{x - 2}$.$h15sql$, $h15sql$3x + 11ln(abs(x - 2)) + c$h15sql$, $h15sql$H(x) = 3x + 11\ln|x - 2| + c$h15sql$, 3, 8, ARRAY[]::text[]),
  ('h15a_bepaald', 'h15a_bepaald', $h15sql$Bereken exact $\displaystyle\int_{0}^{1} \dfrac{x + 3}{x + 1}\,\mathrm{d}x$.$h15sql$, $h15sql$1 + 2ln(2)$h15sql$, $h15sql$1 + 2\ln(2)$h15sql$, 1, 1, ARRAY[]::text[]),
  ('h15a_bepaald', 'h15a_bepaald', $h15sql$Bereken exact $\displaystyle\int_{0}^{2} \dfrac{2x + 5}{x + 2}\,\mathrm{d}x$.$h15sql$, $h15sql$4 + ln(2)$h15sql$, $h15sql$4 + \ln(2)$h15sql$, 1, 2, ARRAY[]::text[]),
  ('h15a_bepaald', 'h15a_bepaald', $h15sql$Bereken exact $\displaystyle\int_{1}^{3} \dfrac{3x - 1}{x + 1}\,\mathrm{d}x$.$h15sql$, $h15sql$6 - 4ln(2)$h15sql$, $h15sql$6 - 4\ln(2)$h15sql$, 1, 3, ARRAY[]::text[]),
  ('h15a_bepaald', 'h15a_bepaald', $h15sql$Bereken exact $\displaystyle\int_{0}^{1} \dfrac{4x + 1}{2x + 1}\,\mathrm{d}x$.$h15sql$, $h15sql$2 - (1/2)ln(3)$h15sql$, $h15sql$2 - \tfrac{1}{2}\ln(3)$h15sql$, 2, 4, ARRAY[$h15sql$2 - 0,5ln(3)$h15sql$]::text[]),
  ('h15a_bepaald', 'h15a_bepaald', $h15sql$Bereken exact $\displaystyle\int_{0}^{3} \dfrac{x + 2}{x + 1}\,\mathrm{d}x$.$h15sql$, $h15sql$3 + 2ln(2)$h15sql$, $h15sql$3 + 2\ln(2)$h15sql$, 2, 5, ARRAY[$h15sql$3 + ln(4)$h15sql$]::text[]),
  ('h15a_bepaald', 'h15a_bepaald', $h15sql$Bereken exact $\displaystyle\int_{1}^{2} \dfrac{5 - x}{x + 1}\,\mathrm{d}x$.$h15sql$, $h15sql$-1 + 6ln(3/2)$h15sql$, $h15sql$-1 + 6\ln\left(\dfrac{3}{2}\right)$h15sql$, 2, 6, ARRAY[$h15sql$6ln(3/2) - 1$h15sql$]::text[]),
  ('h15a_bepaald', 'h15a_bepaald', $h15sql$Bereken exact $\displaystyle\int_{0}^{1} \dfrac{2x + 3}{x + 2}\,\mathrm{d}x$.$h15sql$, $h15sql$2 + ln(2/3)$h15sql$, $h15sql$2 + \ln\left(\dfrac{2}{3}\right)$h15sql$, 3, 7, ARRAY[$h15sql$2 - ln(3/2)$h15sql$, $h15sql$2 + ln(2) - ln(3)$h15sql$]::text[]),
  ('h15a_bepaald', 'h15a_bepaald', $h15sql$Bereken exact $\displaystyle\int_{2}^{4} \dfrac{3x - 2}{x - 1}\,\mathrm{d}x$.$h15sql$, $h15sql$6 + ln(3)$h15sql$, $h15sql$6 + \ln(3)$h15sql$, 3, 8, ARRAY[]::text[]),
  ('h15a_oppervlakte', 'h15a_oppervlakte', $h15sql$Het vlakdeel $V$ wordt ingesloten door de grafiek van $f(x) = \dfrac{x + 3}{x + 1}$, de $x$-as en de lijnen $x = 0$ en $x = 1$. Bereken exact de oppervlakte van $V$.$h15sql$, $h15sql$1 + 2ln(2)$h15sql$, $h15sql$1 + 2\ln(2)$h15sql$, 1, 1, ARRAY[]::text[]),
  ('h15a_oppervlakte', 'h15a_oppervlakte', $h15sql$Het vlakdeel $V$ wordt ingesloten door de grafiek van $f(x) = \dfrac{2x + 4}{x + 1}$ en de lijn $y = 2$, tussen $x = 0$ en $x = 1$. Bereken exact de oppervlakte van $V$.$h15sql$, $h15sql$2ln(2)$h15sql$, $h15sql$2\ln(2)$h15sql$, 1, 2, ARRAY[$h15sql$ln(4)$h15sql$]::text[]),
  ('h15a_oppervlakte', 'h15a_oppervlakte', $h15sql$Het vlakdeel $V$ wordt ingesloten door de grafiek van $f(x) = \dfrac{3x + 6}{x + 1}$, de $x$-as en de lijnen $x = 0$ en $x = 2$. Bereken exact de oppervlakte van $V$.$h15sql$, $h15sql$6 + 3ln(3)$h15sql$, $h15sql$6 + 3\ln(3)$h15sql$, 1, 3, ARRAY[]::text[]),
  ('h15a_oppervlakte', 'h15a_oppervlakte', $h15sql$Voor elke $a > 0$ sluit de grafiek van $f(x) = \dfrac{a}{x + 1}$ met de $x$-as en de lijnen $x = 0$ en $x = 1$ een vlakdeel $V_a$ in. Bereken exact de waarde van $a$ waarvoor de oppervlakte van $V_a$ gelijk is aan $2\ln(2)$.$h15sql$, $h15sql$2$h15sql$, $h15sql$a = 2$h15sql$, 2, 4, ARRAY[$h15sql$a = 2$h15sql$, $h15sql$a=2$h15sql$]::text[]),
  ('h15a_oppervlakte', 'h15a_oppervlakte', $h15sql$Het vlakdeel $V$ wordt ingesloten door de grafiek van $f(x) = \dfrac{x + 5}{x + 1}$ en de lijn $y = 1$, tussen $x = 0$ en $x = 3$. Bereken exact de oppervlakte van $V$.$h15sql$, $h15sql$8ln(2)$h15sql$, $h15sql$8\ln(2)$h15sql$, 2, 5, ARRAY[$h15sql$4ln(4)$h15sql$]::text[]),
  ('h15a_oppervlakte', 'h15a_oppervlakte', $h15sql$Het vlakdeel $V$ wordt ingesloten door de grafiek van $f(x) = \dfrac{4x + 2}{x + 2}$, de $x$-as en de lijnen $x = 0$ en $x = 2$. Bereken exact de oppervlakte van $V$.$h15sql$, $h15sql$8 - 6ln(2)$h15sql$, $h15sql$8 - 6\ln(2)$h15sql$, 2, 6, ARRAY[]::text[]),
  ('h15a_oppervlakte', 'h15a_oppervlakte', $h15sql$Voor elke $p > 0$ sluit de grafiek van $f(x) = \dfrac{3}{x + 2}$ met de $x$-as en de lijnen $x = 0$ en $x = p$ een vlakdeel $V_p$ in. Bereken exact de waarde van $p$ waarvoor de oppervlakte van $V_p$ gelijk is aan $\ln(8)$.$h15sql$, $h15sql$2$h15sql$, $h15sql$p = 2$h15sql$, 3, 7, ARRAY[$h15sql$p = 2$h15sql$, $h15sql$p=2$h15sql$]::text[]),
  ('h15a_oppervlakte', 'h15a_oppervlakte', $h15sql$Het vlakdeel $V$ wordt ingesloten door de grafieken van $f(x) = \dfrac{2x + 1}{x + 1}$ en $g(x) = \dfrac{x + 2}{x + 1}$ en de lijnen $x = 0$ en $x = 1$. Bereken exact de oppervlakte van $V$.$h15sql$, $h15sql$2ln(2) - 1$h15sql$, $h15sql$2\ln(2) - 1$h15sql$, 3, 8, ARRAY[]::text[]),
  ('h15b_verhouding', 'h15b_verhouding', $h15sql$De grafiek van $f(x) = x$ snijdt de rechthoek met hoekpunten $(0, 0)$, $(4, 0)$, $(4, 4)$ en $(0, 4)$ in een onderste vlakdeel $V$ en een bovenste vlakdeel $W$. Bereken de verhouding $O(V) : O(W)$.$h15sql$, $h15sql$1 : 1$h15sql$, $h15sql$1 : 1$h15sql$, 1, 1, ARRAY[$h15sql$1:1$h15sql$, $h15sql$1/1$h15sql$]::text[]),
  ('h15b_verhouding', 'h15b_verhouding', $h15sql$De grafiek van $f(x) = x^{2}$ en de lijn $y = 9$ sluiten op $[0, 3]$ twee vlakdelen in: $V$ onder de parabool en $W$ tussen de parabool en de lijn $y = 9$. Bereken de verhouding $O(V) : O(W)$.$h15sql$, $h15sql$1 : 2$h15sql$, $h15sql$1 : 2$h15sql$, 1, 2, ARRAY[$h15sql$1:2$h15sql$, $h15sql$1/2$h15sql$]::text[]),
  ('h15b_verhouding', 'h15b_verhouding', $h15sql$De grafiek van $f(x) = \sqrt{x}$ en de lijn $y = 3$ sluiten op $[0, 9]$ twee vlakdelen in: $V$ onder de grafiek en $W$ tussen de grafiek en $y = 3$. Bereken de verhouding $O(V) : O(W)$.$h15sql$, $h15sql$2 : 1$h15sql$, $h15sql$2 : 1$h15sql$, 1, 3, ARRAY[$h15sql$2:1$h15sql$, $h15sql$2/1$h15sql$, $h15sql$2$h15sql$]::text[]),
  ('h15b_verhouding', 'h15b_verhouding', $h15sql$De grafiek van $f(x) = x^{3}$ en de lijn $y = 8$ sluiten op $[0, 2]$ twee vlakdelen in: $V$ onder de grafiek en $W$ tussen de grafiek en $y = 8$. Bereken de verhouding $O(V) : O(W)$.$h15sql$, $h15sql$1 : 3$h15sql$, $h15sql$1 : 3$h15sql$, 2, 4, ARRAY[$h15sql$1:3$h15sql$, $h15sql$1/3$h15sql$]::text[]),
  ('h15b_verhouding', 'h15b_verhouding', $h15sql$De grafieken van $f(x) = x$ en $g(x) = x^{2}$ sluiten op $[0, 1]$ het vlakdeel $V$ in. Het vlakdeel $W$ ligt onder $g$ op datzelfde interval. Bereken de verhouding $O(V) : O(W)$.$h15sql$, $h15sql$1 : 2$h15sql$, $h15sql$1 : 2$h15sql$, 2, 5, ARRAY[$h15sql$1:2$h15sql$, $h15sql$1/2$h15sql$]::text[]),
  ('h15b_verhouding', 'h15b_verhouding', $h15sql$De grafieken van $f(x) = \sqrt{x}$ en $g(x) = x$ sluiten op $[0, 1]$ het vlakdeel $V$ in. Het vlakdeel $W$ ligt onder $g$ op datzelfde interval. Bereken de verhouding $O(V) : O(W)$.$h15sql$, $h15sql$1 : 3$h15sql$, $h15sql$1 : 3$h15sql$, 2, 6, ARRAY[$h15sql$1:3$h15sql$, $h15sql$1/3$h15sql$]::text[]),
  ('h15b_verhouding', 'h15b_verhouding', $h15sql$Voor elke $a > 0$ deelt de lijn $y = ax$ de rechthoek met hoekpunten $(0, 0)$, $(1, 0)$, $(1, a)$ en $(0, a)$ in een onderste vlakdeel $V$ en een bovenste vlakdeel $W$. Bereken de verhouding $O(V) : O(W)$. Die verhouding hangt niet van $a$ af.$h15sql$, $h15sql$1 : 1$h15sql$, $h15sql$1 : 1$h15sql$, 3, 7, ARRAY[$h15sql$1:1$h15sql$]::text[]),
  ('h15b_verhouding', 'h15b_verhouding', $h15sql$De grafiek van $f(x) = 6x - x^{2}$ en de $x$-as sluiten op $[0, 6]$ een vlakdeel in. De lijn $x = 3$ deelt dat vlakdeel in $V$ links en $W$ rechts. Bereken de verhouding $O(V) : O(W)$.$h15sql$, $h15sql$1 : 1$h15sql$, $h15sql$1 : 1$h15sql$, 3, 8, ARRAY[$h15sql$1:1$h15sql$]::text[]),
  ('h15b_parameter', 'h15b_parameter', $h15sql$Voor elke $p > 0$ sluit de grafiek van $f(x) = x$ met de $x$-as en de lijn $x = p$ een vlakdeel $V_p$ in. Bereken exact de waarde van $p$ waarvoor de oppervlakte van $V_p$ gelijk is aan $8$.$h15sql$, $h15sql$4$h15sql$, $h15sql$p = 4$h15sql$, 1, 1, ARRAY[$h15sql$p = 4$h15sql$, $h15sql$p=4$h15sql$]::text[]),
  ('h15b_parameter', 'h15b_parameter', $h15sql$Voor elke $p > 0$ sluit de grafiek van $f(x) = x^{2}$ met de $x$-as en de lijn $x = p$ een vlakdeel $V_p$ in. Bereken exact de waarde van $p$ waarvoor de oppervlakte van $V_p$ gelijk is aan $9$.$h15sql$, $h15sql$3$h15sql$, $h15sql$p = 3$h15sql$, 1, 2, ARRAY[$h15sql$p = 3$h15sql$, $h15sql$p=3$h15sql$]::text[]),
  ('h15b_parameter', 'h15b_parameter', $h15sql$Voor elke $p > 0$ sluit de grafiek van $f(x) = \sqrt{x}$ met de $x$-as en de lijn $x = p$ een vlakdeel $V_p$ in. Bereken exact de waarde van $p$ waarvoor de oppervlakte van $V_p$ gelijk is aan $\dfrac{16}{3}$.$h15sql$, $h15sql$4$h15sql$, $h15sql$p = 4$h15sql$, 1, 3, ARRAY[$h15sql$p = 4$h15sql$, $h15sql$p=4$h15sql$]::text[]),
  ('h15b_parameter', 'h15b_parameter', $h15sql$Voor elke $a$ met $0 < a < 4$ zijn gegeven $f(x) = 4 - x^{2}$ en $g(x) = a - x^{2}$. Het vlakdeel $V$ ligt tussen de grafieken van $f$ en $g$. Het vlakdeel $W$ ligt onder de grafiek van $g$, tot aan de $x$-as. Bereken exact de waarde van $a$ waarvoor $O(V) = O(W)$.$h15sql$, $h15sql$12/5$h15sql$, $h15sql$a = \dfrac{12}{5}$h15sql$, 2, 4, ARRAY[$h15sql$a = 12/5$h15sql$, $h15sql$a=12/5$h15sql$, $h15sql$2,4$h15sql$, $h15sql$2.4$h15sql$]::text[]),
  ('h15b_parameter', 'h15b_parameter', $h15sql$Voor elke $p > 1$ sluit de grafiek van $f(x) = \dfrac{1}{x}$ met de $x$-as en de lijnen $x = 1$ en $x = p$ een vlakdeel $V_p$ in. Bereken exact de waarde van $p$ waarvoor de oppervlakte van $V_p$ gelijk is aan $\ln(3)$.$h15sql$, $h15sql$3$h15sql$, $h15sql$p = 3$h15sql$, 2, 5, ARRAY[$h15sql$p = 3$h15sql$, $h15sql$p=3$h15sql$]::text[]),
  ('h15b_parameter', 'h15b_parameter', $h15sql$Voor elke $a > 0$ snijden de grafieken van $f(x) = x$ en $g(x) = ax^{2}$ elkaar in de oorsprong en in $\left(\dfrac{1}{a}, \dfrac{1}{a}\right)$. Het vlakdeel $V_a$ ligt daartussen. Bereken exact de waarde van $a$ waarvoor de oppervlakte van $V_a$ gelijk is aan $\dfrac{1}{24}$.$h15sql$, $h15sql$2$h15sql$, $h15sql$a = 2$h15sql$, 2, 6, ARRAY[$h15sql$a = 2$h15sql$, $h15sql$a=2$h15sql$]::text[]),
  ('h15b_parameter', 'h15b_parameter', $h15sql$Voor elke $p > 0$ sluit de grafiek van $f(x) = e^{x}$ met de $x$-as, de $y$-as en de lijn $x = p$ een vlakdeel $V_p$ in. Bereken exact de waarde van $p$ waarvoor de oppervlakte van $V_p$ gelijk is aan $e^{2} - 1$.$h15sql$, $h15sql$2$h15sql$, $h15sql$p = 2$h15sql$, 3, 7, ARRAY[$h15sql$p = 2$h15sql$, $h15sql$p=2$h15sql$]::text[]),
  ('h15b_parameter', 'h15b_parameter', $h15sql$Voor elke $p > 0$ sluit de grafiek van $f(x) = p(4 - x^{2})$ met de $x$-as een vlakdeel $V_p$ in. Bereken exact de waarde van $p$ waarvoor de oppervlakte van $V_p$ gelijk is aan $16$.$h15sql$, $h15sql$3/2$h15sql$, $h15sql$p = \dfrac{3}{2}$h15sql$, 3, 8, ARRAY[$h15sql$p = 3/2$h15sql$, $h15sql$p=3/2$h15sql$, $h15sql$1,5$h15sql$, $h15sql$1.5$h15sql$]::text[]),
  ('h15c_xas', 'h15c_xas', $h15sql$Het vlakdeel $V$ wordt ingesloten door de grafiek van $f(x) = x$, de $x$-as en de lijn $x = 3$. Het lichaam $L$ ontstaat als $V$ wentelt om de $x$-as. Bereken exact de inhoud van $L$.$h15sql$, $h15sql$9pi$h15sql$, $h15sql$9\pi$h15sql$, 1, 1, ARRAY[$h15sql$9*pi$h15sql$]::text[]),
  ('h15c_xas', 'h15c_xas', $h15sql$Het vlakdeel $V$ wordt ingesloten door de lijn $y = 2$, de $x$-as en de lijnen $x = 0$ en $x = 3$. Het lichaam $L$ ontstaat als $V$ wentelt om de $x$-as. Bereken exact de inhoud van $L$.$h15sql$, $h15sql$12pi$h15sql$, $h15sql$12\pi$h15sql$, 1, 2, ARRAY[$h15sql$12*pi$h15sql$]::text[]),
  ('h15c_xas', 'h15c_xas', $h15sql$Het vlakdeel $V$ wordt ingesloten door de grafiek van $f(x) = \sqrt{x}$, de $x$-as en de lijn $x = 4$. Het lichaam $L$ ontstaat als $V$ wentelt om de $x$-as. Bereken exact de inhoud van $L$.$h15sql$, $h15sql$8pi$h15sql$, $h15sql$8\pi$h15sql$, 1, 3, ARRAY[$h15sql$8*pi$h15sql$]::text[]),
  ('h15c_xas', 'h15c_xas', $h15sql$Het vlakdeel $V$ wordt ingesloten door de grafiek van $f(x) = x + 1$, de $x$-as en de lijnen $x = 0$ en $x = 1$. Het lichaam $L$ ontstaat als $V$ wentelt om de $x$-as. Bereken exact de inhoud van $L$.$h15sql$, $h15sql$(7/3)pi$h15sql$, $h15sql$\dfrac{7}{3}\pi$h15sql$, 2, 4, ARRAY[$h15sql$7pi/3$h15sql$, $h15sql$(7/3)*pi$h15sql$]::text[]),
  ('h15c_xas', 'h15c_xas', $h15sql$Het vlakdeel $V$ wordt ingesloten door de lijn $y = 3 - x$, de $x$-as en de $y$-as. Het lichaam $L$ ontstaat als $V$ wentelt om de $x$-as. Bereken exact de inhoud van $L$.$h15sql$, $h15sql$9pi$h15sql$, $h15sql$9\pi$h15sql$, 2, 5, ARRAY[$h15sql$9*pi$h15sql$]::text[]),
  ('h15c_xas', 'h15c_xas', $h15sql$Het vlakdeel $V$ wordt ingesloten door de grafieken van $f(x) = x$ en $g(x) = x^{2}$. Het lichaam $L$ ontstaat als $V$ wentelt om de $x$-as. Bereken exact de inhoud van $L$.$h15sql$, $h15sql$(2/15)pi$h15sql$, $h15sql$\dfrac{2}{15}\pi$h15sql$, 2, 6, ARRAY[$h15sql$2pi/15$h15sql$, $h15sql$(2/15)*pi$h15sql$]::text[]),
  ('h15c_xas', 'h15c_xas', $h15sql$Het vlakdeel $V$ wordt ingesloten door de lijnen $y = 2$ en $y = x$ en de $y$-as. Het lichaam $L$ ontstaat als $V$ wentelt om de $x$-as. Bereken exact de inhoud van $L$.$h15sql$, $h15sql$(16/3)pi$h15sql$, $h15sql$\dfrac{16}{3}\pi$h15sql$, 3, 7, ARRAY[$h15sql$16pi/3$h15sql$, $h15sql$(16/3)*pi$h15sql$]::text[]),
  ('h15c_xas', 'h15c_xas', $h15sql$Het vlakdeel $V$ wordt ingesloten door de grafiek van $f(x) = 2x$, de $x$-as en de lijn $x = 2$. Het lichaam $L$ ontstaat als $V$ wentelt om de $x$-as. Bereken exact de inhoud van $L$.$h15sql$, $h15sql$(32/3)pi$h15sql$, $h15sql$\dfrac{32}{3}\pi$h15sql$, 3, 8, ARRAY[$h15sql$32pi/3$h15sql$, $h15sql$(32/3)*pi$h15sql$]::text[]),
  ('h15c_yas', 'h15c_yas', $h15sql$Het vlakdeel $V$ wordt ingesloten door de lijn $y = x$, de $y$-as en de lijn $y = 2$. Het lichaam $L$ ontstaat als $V$ wentelt om de $y$-as. Bereken exact de inhoud van $L$.$h15sql$, $h15sql$(8/3)pi$h15sql$, $h15sql$\dfrac{8}{3}\pi$h15sql$, 1, 1, ARRAY[$h15sql$8pi/3$h15sql$, $h15sql$(8/3)*pi$h15sql$]::text[]),
  ('h15c_yas', 'h15c_yas', $h15sql$Het vlakdeel $V$ wordt ingesloten door de grafiek van $y = \sqrt{x}$, de $x$-as en de lijn $x = 4$. Het lichaam $L$ ontstaat als $V$ wentelt om de $y$-as. Bereken exact de inhoud van $L$.$h15sql$, $h15sql$(32/5)pi$h15sql$, $h15sql$\dfrac{32}{5}\pi$h15sql$, 1, 2, ARRAY[$h15sql$32pi/5$h15sql$, $h15sql$(32/5)*pi$h15sql$]::text[]),
  ('h15c_yas', 'h15c_yas', $h15sql$Het vlakdeel $V$ wordt ingesloten door de grafiek van $y = x^{2}$, de $x$-as en de lijn $x = 2$. Het lichaam $L$ ontstaat als $V$ wentelt om de $y$-as. Bereken exact de inhoud van $L$.$h15sql$, $h15sql$8pi$h15sql$, $h15sql$8\pi$h15sql$, 1, 3, ARRAY[$h15sql$8*pi$h15sql$]::text[]),
  ('h15c_yas', 'h15c_yas', $h15sql$Het vlakdeel $V$ wordt ingesloten door de lijn $y = 2x$, de $y$-as en de lijn $y = 4$. Het lichaam $L$ ontstaat als $V$ wentelt om de $y$-as. Bereken exact de inhoud van $L$.$h15sql$, $h15sql$(16/3)pi$h15sql$, $h15sql$\dfrac{16}{3}\pi$h15sql$, 2, 4, ARRAY[$h15sql$16pi/3$h15sql$, $h15sql$(16/3)*pi$h15sql$]::text[]),
  ('h15c_yas', 'h15c_yas', $h15sql$Het vlakdeel $V$ wordt ingesloten door de lijnen $y = x$ en $y = 2x$ en de lijn $y = 2$. Het lichaam $L$ ontstaat als $V$ wentelt om de $y$-as. Bereken exact de inhoud van $L$.$h15sql$, $h15sql$2pi$h15sql$, $h15sql$2\pi$h15sql$, 2, 5, ARRAY[$h15sql$2*pi$h15sql$]::text[]),
  ('h15c_yas', 'h15c_yas', $h15sql$Het vlakdeel $V$ is de rechthoek met hoekpunten $(0, 0)$, $(3, 0)$, $(3, 2)$ en $(0, 2)$. Het lichaam $L$ ontstaat als $V$ wentelt om de $y$-as. Bereken exact de inhoud van $L$.$h15sql$, $h15sql$18pi$h15sql$, $h15sql$18\pi$h15sql$, 2, 6, ARRAY[$h15sql$18*pi$h15sql$]::text[]),
  ('h15c_yas', 'h15c_yas', $h15sql$Het vlakdeel $V$ wordt ingesloten door de grafiek van $y = 4 - x^{2}$ en de coördinaatassen in het eerste kwadrant. Het lichaam $L$ ontstaat als $V$ wentelt om de $y$-as. Bereken exact de inhoud van $L$.$h15sql$, $h15sql$8pi$h15sql$, $h15sql$8\pi$h15sql$, 3, 7, ARRAY[$h15sql$8*pi$h15sql$]::text[]),
  ('h15c_yas', 'h15c_yas', $h15sql$Het vlakdeel $V$ wordt ingesloten door de grafieken van $x = y$ en $x = y^{2}$, met $0 \le y \le 1$. Het lichaam $L$ ontstaat als $V$ wentelt om de $y$-as. Bereken exact de inhoud van $L$.$h15sql$, $h15sql$(2/15)pi$h15sql$, $h15sql$\dfrac{2}{15}\pi$h15sql$, 3, 8, ARRAY[$h15sql$2pi/15$h15sql$, $h15sql$(2/15)*pi$h15sql$]::text[]),
  ('h15c_vergelijk', 'h15c_vergelijk', $h15sql$Voor elke $p > 0$ ontstaat het lichaam $L_p$ als het vlakdeel onder $y = x$ van $x = 0$ tot $x = p$ wentelt om de $x$-as. Bereken exact de waarde van $p$ waarvoor de inhoud van $L_p$ gelijk is aan $9\pi$.$h15sql$, $h15sql$3$h15sql$, $h15sql$p = 3$h15sql$, 1, 1, ARRAY[$h15sql$p = 3$h15sql$, $h15sql$p=3$h15sql$]::text[]),
  ('h15c_vergelijk', 'h15c_vergelijk', $h15sql$Voor elke $p > 0$ ontstaat het lichaam $L_p$ als het vlakdeel onder $y = \sqrt{x}$ van $x = 0$ tot $x = p$ wentelt om de $x$-as. Bereken exact de waarde van $p$ waarvoor de inhoud van $L_p$ gelijk is aan $8\pi$.$h15sql$, $h15sql$4$h15sql$, $h15sql$p = 4$h15sql$, 1, 2, ARRAY[$h15sql$p = 4$h15sql$, $h15sql$p=4$h15sql$]::text[]),
  ('h15c_vergelijk', 'h15c_vergelijk', $h15sql$Voor elke $a > 0$ wordt het vlakdeel onder $y = x^{2}$ van $x = 0$ tot $x = a$ bekeken. Lichaam $L$ ontstaat bij wentelen om de $x$-as, lichaam $M$ bij wentelen om de $y$-as. Bereken exact de waarde van $a$ waarvoor de inhoud van $L$ gelijk is aan de inhoud van $M$.$h15sql$, $h15sql$5/2$h15sql$, $h15sql$a = \dfrac{5}{2}$h15sql$, 2, 3, ARRAY[$h15sql$a = 5/2$h15sql$, $h15sql$a=5/2$h15sql$, $h15sql$2,5$h15sql$, $h15sql$2.5$h15sql$]::text[]),
  ('h15c_vergelijk', 'h15c_vergelijk', $h15sql$Voor elke $k > 0$ ontstaat het lichaam $L_k$ als de rechthoek onder $y = k$ van $x = 0$ tot $x = 2$ wentelt om de $x$-as. Bereken exact de waarde van $k$ waarvoor de inhoud van $L_k$ gelijk is aan $18\pi$.$h15sql$, $h15sql$3$h15sql$, $h15sql$k = 3$h15sql$, 2, 4, ARRAY[$h15sql$k = 3$h15sql$, $h15sql$k=3$h15sql$]::text[]),
  ('h15c_vergelijk', 'h15c_vergelijk', $h15sql$Voor elke $p > 0$ ontstaat het lichaam $L_p$ als het vlakdeel onder $y = \sqrt{x}$ van $x = 0$ tot $x = p$ wentelt om de $y$-as. Bereken exact de waarde van $p$ waarvoor de inhoud van $L_p$ gelijk is aan $\dfrac{32}{5}\pi$.$h15sql$, $h15sql$4$h15sql$, $h15sql$p = 4$h15sql$, 2, 5, ARRAY[$h15sql$p = 4$h15sql$, $h15sql$p=4$h15sql$]::text[]),
  ('h15c_vergelijk', 'h15c_vergelijk', $h15sql$Lichaam $L$ ontstaat als het vlakdeel onder $y = x$ van $x = 0$ tot $x = 2$ wentelt om de $x$-as. Lichaam $M_p$ ontstaat op dezelfde manier, maar tot $x = p$ met $p > 0$. Bereken exact de waarde van $p$ waarvoor de inhoud van $M_p$ twee keer zo groot is als de inhoud van $L$.$h15sql$, $h15sql$16^(1/3)$h15sql$, $h15sql$p = \sqrt[3]{16}$h15sql$, 3, 6, ARRAY[$h15sql$2*2^(1/3)$h15sql$, $h15sql$p = 16^(1/3)$h15sql$]::text[]),
  ('h15c_vergelijk', 'h15c_vergelijk', $h15sql$Voor elke $a > 0$ wordt het vlakdeel onder $y = \sqrt{x}$ van $x = 0$ tot $x = a$ bekeken. Lichaam $L$ ontstaat bij wentelen om de $x$-as, lichaam $M$ bij wentelen om de $y$-as. Bereken exact de waarde van $a$ waarvoor de inhoud van $L$ gelijk is aan de inhoud van $M$.$h15sql$, $h15sql$25/4$h15sql$, $h15sql$a = \dfrac{25}{4}$h15sql$, 3, 7, ARRAY[$h15sql$a = 25/4$h15sql$, $h15sql$a=25/4$h15sql$, $h15sql$6,25$h15sql$, $h15sql$6.25$h15sql$]::text[]),
  ('h15c_vergelijk', 'h15c_vergelijk', $h15sql$Lichaam $L$ ontstaat als het vlakdeel tussen $y = 2$ en $y = x$ op $[0, 2]$ wentelt om de $x$-as. Voor elke $q > 0$ ontstaat lichaam $M_q$ als de rechthoek onder $y = q$ van $x = 0$ tot $x = 3$ wentelt om de $x$-as. Bereken exact de waarde van $q$ waarvoor de inhoud van $M_q$ gelijk is aan de inhoud van $L$.$h15sql$, $h15sql$4/3$h15sql$, $h15sql$q = \dfrac{4}{3}$h15sql$, 3, 8, ARRAY[$h15sql$q = 4/3$h15sql$, $h15sql$q=4/3$h15sql$]::text[])
) AS v(topic_slug, cluster_slug, latex_body, answer, latex_answer, difficulty, order_index, alternatives)
JOIN public.topics_new t ON t.slug = v.topic_slug AND t.site = 'integralen'
JOIN public.topic_clusters_new cl ON cl.slug = v.cluster_slug AND cl.topic_id = t.id
WHERE NOT EXISTS (
  SELECT 1 FROM public.questions_new bestaand
  WHERE bestaand.cluster_id = cl.id AND bestaand.latex_body = v.latex_body
);

-- 5. Stappen (step_order 0 t/m 3)
INSERT INTO public.question_steps_new (question_id, step_order, step_description)
SELECT vr.id, v.step_order, v.step_description
FROM (VALUES
  ('h15a_primitiveren', 'h15a_primitief', $h15sql$Primitiveer $f(x) = \dfrac{x + 3}{x + 1}$.$h15sql$, 0, $h15sql$Alleen deel 2 van de driedeling speelt hier: bereken de goede integraal. Schrijf de breuk eerst als een getal plus een breuk met een constante teller.$h15sql$),
  ('h15a_primitiveren', 'h15a_primitief', $h15sql$Primitiveer $f(x) = \dfrac{x + 3}{x + 1}$.$h15sql$, 1, $h15sql$$(x + 3) = 1\cdot(x + 1) + 2$, dus $f(x) = 1 + \dfrac{2}{x + 1}$.$h15sql$),
  ('h15a_primitiveren', 'h15a_primitief', $h15sql$Primitiveer $f(x) = \dfrac{x + 3}{x + 1}$.$h15sql$, 2, $h15sql$Een primitieve van $1$ is $x$. De kern van de tweede term is $x + 1$, en die kern heeft afgeleide $1$, dus een primitieve van $\dfrac{2}{x + 1}$ is $2\ln|x + 1|$.$h15sql$),
  ('h15a_primitiveren', 'h15a_primitief', $h15sql$Primitiveer $f(x) = \dfrac{x + 3}{x + 1}$.$h15sql$, 3, $h15sql$$F(x) = x + 2\ln|x + 1| + c$. Controle: de afgeleide is $1 + \dfrac{2}{x + 1} = \dfrac{x + 3}{x + 1}$.$h15sql$),
  ('h15a_primitiveren', 'h15a_primitief', $h15sql$Primitiveer $f(x) = \dfrac{2x + 5}{x + 2}$.$h15sql$, 0, $h15sql$Alleen deel 2 van de driedeling speelt hier: bereken de goede integraal. Schrijf de breuk als een getal plus een breuk met een constante teller.$h15sql$),
  ('h15a_primitiveren', 'h15a_primitief', $h15sql$Primitiveer $f(x) = \dfrac{2x + 5}{x + 2}$.$h15sql$, 1, $h15sql$$2x + 5 = 2(x + 2) + 1$, dus $f(x) = 2 + \dfrac{1}{x + 2}$.$h15sql$),
  ('h15a_primitiveren', 'h15a_primitief', $h15sql$Primitiveer $f(x) = \dfrac{2x + 5}{x + 2}$.$h15sql$, 2, $h15sql$Een primitieve van $2$ is $2x$. De kern is $x + 2$, met afgeleide $1$, dus een primitieve van $\dfrac{1}{x + 2}$ is $\ln|x + 2|$.$h15sql$),
  ('h15a_primitiveren', 'h15a_primitief', $h15sql$Primitiveer $f(x) = \dfrac{2x + 5}{x + 2}$.$h15sql$, 3, $h15sql$$F(x) = 2x + \ln|x + 2| + c$. Controle: de afgeleide is $2 + \dfrac{1}{x + 2} = f(x)$.$h15sql$),
  ('h15a_primitiveren', 'h15a_primitief', $h15sql$Primitiveer $f(x) = \dfrac{3x - 1}{x + 1}$.$h15sql$, 0, $h15sql$Alleen deel 2 van de driedeling speelt hier: bereken de goede integraal. Schrijf de breuk als een getal plus een breuk met een constante teller.$h15sql$),
  ('h15a_primitiveren', 'h15a_primitief', $h15sql$Primitiveer $f(x) = \dfrac{3x - 1}{x + 1}$.$h15sql$, 1, $h15sql$$3x - 1 = 3(x + 1) - 4$, dus $f(x) = 3 - \dfrac{4}{x + 1}$.$h15sql$),
  ('h15a_primitiveren', 'h15a_primitief', $h15sql$Primitiveer $f(x) = \dfrac{3x - 1}{x + 1}$.$h15sql$, 2, $h15sql$Een primitieve van $3$ is $3x$. De kern is $x + 1$, dus een primitieve van $-\dfrac{4}{x + 1}$ is $-4\ln|x + 1|$.$h15sql$),
  ('h15a_primitiveren', 'h15a_primitief', $h15sql$Primitiveer $f(x) = \dfrac{3x - 1}{x + 1}$.$h15sql$, 3, $h15sql$$F(x) = 3x - 4\ln|x + 1| + c$. Controle: de afgeleide is $3 - \dfrac{4}{x + 1} = f(x)$.$h15sql$),
  ('h15a_primitiveren', 'h15a_primitief', $h15sql$Primitiveer $f(x) = \dfrac{4x + 1}{2x + 1}$.$h15sql$, 0, $h15sql$Alleen deel 2 van de driedeling speelt hier: bereken de goede integraal. De noemer is niet alleen $x$ plus een getal. Schrijf de breuk toch als een getal plus een restbreuk, en let bij het primitiveren op de afgeleide van de kern.$h15sql$),
  ('h15a_primitiveren', 'h15a_primitief', $h15sql$Primitiveer $f(x) = \dfrac{4x + 1}{2x + 1}$.$h15sql$, 1, $h15sql$$4x + 1 = 2(2x + 1) - 1$, dus $f(x) = 2 - \dfrac{1}{2x + 1}$.$h15sql$),
  ('h15a_primitiveren', 'h15a_primitief', $h15sql$Primitiveer $f(x) = \dfrac{4x + 1}{2x + 1}$.$h15sql$, 2, $h15sql$Een primitieve van $2$ is $2x$. De kern is $2x + 1$, met afgeleide $2$. Een primitieve van $\dfrac{1}{2x + 1}$ is daarom $\dfrac{1}{2}\ln|2x + 1|$, en met het minteken erbij wordt dat $-\dfrac{1}{2}\ln|2x + 1|$.$h15sql$),
  ('h15a_primitiveren', 'h15a_primitief', $h15sql$Primitiveer $f(x) = \dfrac{4x + 1}{2x + 1}$.$h15sql$, 3, $h15sql$$F(x) = 2x - \dfrac{1}{2}\ln|2x + 1| + c$. Controle: de afgeleide is $2 - \dfrac{1}{2x + 1} = f(x)$.$h15sql$),
  ('h15a_primitiveren', 'h15a_primitief', $h15sql$Primitiveer $g(x) = \dfrac{x - 4}{2x + 3}$.$h15sql$, 0, $h15sql$Alleen deel 2 van de driedeling speelt hier: bereken de goede integraal. Schrijf de breuk als een getal plus een restbreuk. De teller van de rest bepaal je door de deling.$h15sql$),
  ('h15a_primitiveren', 'h15a_primitief', $h15sql$Primitiveer $g(x) = \dfrac{x - 4}{2x + 3}$.$h15sql$, 1, $h15sql$$x - 4 = \dfrac{1}{2}(2x + 3) - \dfrac{11}{2}$, dus $g(x) = \dfrac{1}{2} - \dfrac{11/2}{2x + 3}$.$h15sql$),
  ('h15a_primitiveren', 'h15a_primitief', $h15sql$Primitiveer $g(x) = \dfrac{x - 4}{2x + 3}$.$h15sql$, 2, $h15sql$Een primitieve van $\dfrac{1}{2}$ is $\dfrac{1}{2}x$. De kern is $2x + 3$, met afgeleide $2$. Deel de factor $\dfrac{11}{2}$ door $2$: een primitieve van de restterm is $-\dfrac{11}{4}\ln|2x + 3|$.$h15sql$),
  ('h15a_primitiveren', 'h15a_primitief', $h15sql$Primitiveer $g(x) = \dfrac{x - 4}{2x + 3}$.$h15sql$, 3, $h15sql$$G(x) = \dfrac{1}{2}x - \dfrac{11}{4}\ln|2x + 3| + c$. Controle: de afgeleide is $g(x)$.$h15sql$),
  ('h15a_primitiveren', 'h15a_primitief', $h15sql$Primitiveer $f(x) = \dfrac{5 - 2x}{x + 3}$.$h15sql$, 0, $h15sql$Alleen deel 2 van de driedeling speelt hier: bereken de goede integraal. Het minteken bij $x$ hoort bij het getal vóór de restbreuk.$h15sql$),
  ('h15a_primitiveren', 'h15a_primitief', $h15sql$Primitiveer $f(x) = \dfrac{5 - 2x}{x + 3}$.$h15sql$, 1, $h15sql$$5 - 2x = -2(x + 3) + 11$, dus $f(x) = -2 + \dfrac{11}{x + 3}$.$h15sql$),
  ('h15a_primitiveren', 'h15a_primitief', $h15sql$Primitiveer $f(x) = \dfrac{5 - 2x}{x + 3}$.$h15sql$, 2, $h15sql$Een primitieve van $-2$ is $-2x$. De kern is $x + 3$, met afgeleide $1$, dus een primitieve van $\dfrac{11}{x + 3}$ is $11\ln|x + 3|$.$h15sql$),
  ('h15a_primitiveren', 'h15a_primitief', $h15sql$Primitiveer $f(x) = \dfrac{5 - 2x}{x + 3}$.$h15sql$, 3, $h15sql$$F(x) = -2x + 11\ln|x + 3| + c$. Controle: de afgeleide is $-2 + \dfrac{11}{x + 3} = f(x)$.$h15sql$),
  ('h15a_primitiveren', 'h15a_primitief', $h15sql$Primitiveer $f(x) = \dfrac{6x - 1}{3x + 2}$.$h15sql$, 0, $h15sql$Alleen deel 2 van de driedeling speelt hier: bereken de goede integraal. Deel de teller door de noemer. De afgeleide van de kern is $3$, dus daarna deel je door $3$.$h15sql$),
  ('h15a_primitiveren', 'h15a_primitief', $h15sql$Primitiveer $f(x) = \dfrac{6x - 1}{3x + 2}$.$h15sql$, 1, $h15sql$$6x - 1 = 2(3x + 2) - 5$, dus $f(x) = 2 - \dfrac{5}{3x + 2}$.$h15sql$),
  ('h15a_primitiveren', 'h15a_primitief', $h15sql$Primitiveer $f(x) = \dfrac{6x - 1}{3x + 2}$.$h15sql$, 2, $h15sql$Een primitieve van $2$ is $2x$. De kern is $3x + 2$. Een primitieve van $\dfrac{5}{3x + 2}$ is $\dfrac{5}{3}\ln|3x + 2|$.$h15sql$),
  ('h15a_primitiveren', 'h15a_primitief', $h15sql$Primitiveer $f(x) = \dfrac{6x - 1}{3x + 2}$.$h15sql$, 3, $h15sql$$F(x) = 2x - \dfrac{5}{3}\ln|3x + 2| + c$. Controle: de afgeleide is $2 - \dfrac{5}{3x + 2} = f(x)$.$h15sql$),
  ('h15a_primitiveren', 'h15a_primitief', $h15sql$Primitiveer $h(x) = \dfrac{3x + 5}{x - 2}$.$h15sql$, 0, $h15sql$Alleen deel 2 van de driedeling speelt hier: bereken de goede integraal. De noemer is $x - 2$. Schrijf de teller als een veelvoud van die noemer, plus een constante.$h15sql$),
  ('h15a_primitiveren', 'h15a_primitief', $h15sql$Primitiveer $h(x) = \dfrac{3x + 5}{x - 2}$.$h15sql$, 1, $h15sql$$3x + 5 = 3(x - 2) + 11$, dus $h(x) = 3 + \dfrac{11}{x - 2}$.$h15sql$),
  ('h15a_primitiveren', 'h15a_primitief', $h15sql$Primitiveer $h(x) = \dfrac{3x + 5}{x - 2}$.$h15sql$, 2, $h15sql$Een primitieve van $3$ is $3x$. De kern is $x - 2$, met afgeleide $1$, dus een primitieve van $\dfrac{11}{x - 2}$ is $11\ln|x - 2|$.$h15sql$),
  ('h15a_primitiveren', 'h15a_primitief', $h15sql$Primitiveer $h(x) = \dfrac{3x + 5}{x - 2}$.$h15sql$, 3, $h15sql$$H(x) = 3x + 11\ln|x - 2| + c$. Controle: de afgeleide is $3 + \dfrac{11}{x - 2} = h(x)$.$h15sql$),
  ('h15a_bepaald', 'h15a_bepaald', $h15sql$Bereken exact $\displaystyle\int_{0}^{1} \dfrac{x + 3}{x + 1}\,\mathrm{d}x$.$h15sql$, 0, $h15sql$Alleen deel 2 van de driedeling speelt hier: bereken de goede integraal. Herschrijf de breuk en vul daarna de grenzen in.$h15sql$),
  ('h15a_bepaald', 'h15a_bepaald', $h15sql$Bereken exact $\displaystyle\int_{0}^{1} \dfrac{x + 3}{x + 1}\,\mathrm{d}x$.$h15sql$, 1, $h15sql$$\dfrac{x + 3}{x + 1} = 1 + \dfrac{2}{x + 1}$. Op $[0, 1]$ is de noemer positief.$h15sql$),
  ('h15a_bepaald', 'h15a_bepaald', $h15sql$Bereken exact $\displaystyle\int_{0}^{1} \dfrac{x + 3}{x + 1}\,\mathrm{d}x$.$h15sql$, 2, $h15sql$Een primitieve is $F(x) = x + 2\ln(x + 1)$.$h15sql$),
  ('h15a_bepaald', 'h15a_bepaald', $h15sql$Bereken exact $\displaystyle\int_{0}^{1} \dfrac{x + 3}{x + 1}\,\mathrm{d}x$.$h15sql$, 3, $h15sql$$F(1) - F(0) = (1 + 2\ln(2)) - 0 = 1 + 2\ln(2)$.$h15sql$),
  ('h15a_bepaald', 'h15a_bepaald', $h15sql$Bereken exact $\displaystyle\int_{0}^{2} \dfrac{2x + 5}{x + 2}\,\mathrm{d}x$.$h15sql$, 0, $h15sql$Alleen deel 2 van de driedeling speelt hier: bereken de goede integraal. Herschrijf de breuk en vul daarna de grenzen in.$h15sql$),
  ('h15a_bepaald', 'h15a_bepaald', $h15sql$Bereken exact $\displaystyle\int_{0}^{2} \dfrac{2x + 5}{x + 2}\,\mathrm{d}x$.$h15sql$, 1, $h15sql$$\dfrac{2x + 5}{x + 2} = 2 + \dfrac{1}{x + 2}$.$h15sql$),
  ('h15a_bepaald', 'h15a_bepaald', $h15sql$Bereken exact $\displaystyle\int_{0}^{2} \dfrac{2x + 5}{x + 2}\,\mathrm{d}x$.$h15sql$, 2, $h15sql$Een primitieve is $F(x) = 2x + \ln(x + 2)$.$h15sql$),
  ('h15a_bepaald', 'h15a_bepaald', $h15sql$Bereken exact $\displaystyle\int_{0}^{2} \dfrac{2x + 5}{x + 2}\,\mathrm{d}x$.$h15sql$, 3, $h15sql$$F(2) - F(0) = (4 + \ln(4)) - \ln(2) = 4 + 2\ln(2) - \ln(2) = 4 + \ln(2)$.$h15sql$),
  ('h15a_bepaald', 'h15a_bepaald', $h15sql$Bereken exact $\displaystyle\int_{1}^{3} \dfrac{3x - 1}{x + 1}\,\mathrm{d}x$.$h15sql$, 0, $h15sql$Alleen deel 2 van de driedeling speelt hier: bereken de goede integraal. Herschrijf de breuk en vul daarna de grenzen in.$h15sql$),
  ('h15a_bepaald', 'h15a_bepaald', $h15sql$Bereken exact $\displaystyle\int_{1}^{3} \dfrac{3x - 1}{x + 1}\,\mathrm{d}x$.$h15sql$, 1, $h15sql$$\dfrac{3x - 1}{x + 1} = 3 - \dfrac{4}{x + 1}$.$h15sql$),
  ('h15a_bepaald', 'h15a_bepaald', $h15sql$Bereken exact $\displaystyle\int_{1}^{3} \dfrac{3x - 1}{x + 1}\,\mathrm{d}x$.$h15sql$, 2, $h15sql$Een primitieve is $F(x) = 3x - 4\ln(x + 1)$.$h15sql$),
  ('h15a_bepaald', 'h15a_bepaald', $h15sql$Bereken exact $\displaystyle\int_{1}^{3} \dfrac{3x - 1}{x + 1}\,\mathrm{d}x$.$h15sql$, 3, $h15sql$$F(3) - F(1) = (9 - 4\ln(4)) - (3 - 4\ln(2)) = 6 - 8\ln(2) + 4\ln(2) = 6 - 4\ln(2)$.$h15sql$),
  ('h15a_bepaald', 'h15a_bepaald', $h15sql$Bereken exact $\displaystyle\int_{0}^{1} \dfrac{4x + 1}{2x + 1}\,\mathrm{d}x$.$h15sql$, 0, $h15sql$Alleen deel 2 van de driedeling speelt hier: bereken de goede integraal. Herschrijf de breuk. De kern is $2x + 1$, dus bij de logaritme deel je door $2$.$h15sql$),
  ('h15a_bepaald', 'h15a_bepaald', $h15sql$Bereken exact $\displaystyle\int_{0}^{1} \dfrac{4x + 1}{2x + 1}\,\mathrm{d}x$.$h15sql$, 1, $h15sql$$\dfrac{4x + 1}{2x + 1} = 2 - \dfrac{1}{2x + 1}$.$h15sql$),
  ('h15a_bepaald', 'h15a_bepaald', $h15sql$Bereken exact $\displaystyle\int_{0}^{1} \dfrac{4x + 1}{2x + 1}\,\mathrm{d}x$.$h15sql$, 2, $h15sql$Een primitieve is $F(x) = 2x - \dfrac{1}{2}\ln(2x + 1)$.$h15sql$),
  ('h15a_bepaald', 'h15a_bepaald', $h15sql$Bereken exact $\displaystyle\int_{0}^{1} \dfrac{4x + 1}{2x + 1}\,\mathrm{d}x$.$h15sql$, 3, $h15sql$$F(1) - F(0) = \left(2 - \dfrac{1}{2}\ln(3)\right) - 0 = 2 - \dfrac{1}{2}\ln(3)$.$h15sql$),
  ('h15a_bepaald', 'h15a_bepaald', $h15sql$Bereken exact $\displaystyle\int_{0}^{3} \dfrac{x + 2}{x + 1}\,\mathrm{d}x$.$h15sql$, 0, $h15sql$Alleen deel 2 van de driedeling speelt hier: bereken de goede integraal. Herschrijf de breuk en vul daarna de grenzen in.$h15sql$),
  ('h15a_bepaald', 'h15a_bepaald', $h15sql$Bereken exact $\displaystyle\int_{0}^{3} \dfrac{x + 2}{x + 1}\,\mathrm{d}x$.$h15sql$, 1, $h15sql$$\dfrac{x + 2}{x + 1} = 1 + \dfrac{1}{x + 1}$.$h15sql$),
  ('h15a_bepaald', 'h15a_bepaald', $h15sql$Bereken exact $\displaystyle\int_{0}^{3} \dfrac{x + 2}{x + 1}\,\mathrm{d}x$.$h15sql$, 2, $h15sql$Een primitieve is $F(x) = x + \ln(x + 1)$.$h15sql$),
  ('h15a_bepaald', 'h15a_bepaald', $h15sql$Bereken exact $\displaystyle\int_{0}^{3} \dfrac{x + 2}{x + 1}\,\mathrm{d}x$.$h15sql$, 3, $h15sql$$F(3) - F(0) = 3 + \ln(4) = 3 + 2\ln(2)$.$h15sql$),
  ('h15a_bepaald', 'h15a_bepaald', $h15sql$Bereken exact $\displaystyle\int_{1}^{2} \dfrac{5 - x}{x + 1}\,\mathrm{d}x$.$h15sql$, 0, $h15sql$Alleen deel 2 van de driedeling speelt hier: bereken de goede integraal. Het minteken bij $x$ hoort in de herschrijving.$h15sql$),
  ('h15a_bepaald', 'h15a_bepaald', $h15sql$Bereken exact $\displaystyle\int_{1}^{2} \dfrac{5 - x}{x + 1}\,\mathrm{d}x$.$h15sql$, 1, $h15sql$$\dfrac{5 - x}{x + 1} = -1 + \dfrac{6}{x + 1}$.$h15sql$),
  ('h15a_bepaald', 'h15a_bepaald', $h15sql$Bereken exact $\displaystyle\int_{1}^{2} \dfrac{5 - x}{x + 1}\,\mathrm{d}x$.$h15sql$, 2, $h15sql$Een primitieve is $F(x) = -x + 6\ln(x + 1)$.$h15sql$),
  ('h15a_bepaald', 'h15a_bepaald', $h15sql$Bereken exact $\displaystyle\int_{1}^{2} \dfrac{5 - x}{x + 1}\,\mathrm{d}x$.$h15sql$, 3, $h15sql$$F(2) - F(1) = (-2 + 6\ln(3)) - (-1 + 6\ln(2)) = -1 + 6\ln\left(\dfrac{3}{2}\right)$.$h15sql$),
  ('h15a_bepaald', 'h15a_bepaald', $h15sql$Bereken exact $\displaystyle\int_{0}^{1} \dfrac{2x + 3}{x + 2}\,\mathrm{d}x$.$h15sql$, 0, $h15sql$Alleen deel 2 van de driedeling speelt hier: bereken de goede integraal. Herschrijf de breuk. De restterm heeft een minteken.$h15sql$),
  ('h15a_bepaald', 'h15a_bepaald', $h15sql$Bereken exact $\displaystyle\int_{0}^{1} \dfrac{2x + 3}{x + 2}\,\mathrm{d}x$.$h15sql$, 1, $h15sql$$2x + 3 = 2(x + 2) - 1$, dus $\dfrac{2x + 3}{x + 2} = 2 - \dfrac{1}{x + 2}$.$h15sql$),
  ('h15a_bepaald', 'h15a_bepaald', $h15sql$Bereken exact $\displaystyle\int_{0}^{1} \dfrac{2x + 3}{x + 2}\,\mathrm{d}x$.$h15sql$, 2, $h15sql$Een primitieve is $F(x) = 2x - \ln(x + 2)$.$h15sql$),
  ('h15a_bepaald', 'h15a_bepaald', $h15sql$Bereken exact $\displaystyle\int_{0}^{1} \dfrac{2x + 3}{x + 2}\,\mathrm{d}x$.$h15sql$, 3, $h15sql$$F(1) - F(0) = (2 - \ln(3)) - (-\ln(2)) = 2 + \ln\left(\dfrac{2}{3}\right)$.$h15sql$),
  ('h15a_bepaald', 'h15a_bepaald', $h15sql$Bereken exact $\displaystyle\int_{2}^{4} \dfrac{3x - 2}{x - 1}\,\mathrm{d}x$.$h15sql$, 0, $h15sql$Alleen deel 2 van de driedeling speelt hier: bereken de goede integraal. De noemer is $x - 1$. Op $[2, 4]$ blijft die positief.$h15sql$),
  ('h15a_bepaald', 'h15a_bepaald', $h15sql$Bereken exact $\displaystyle\int_{2}^{4} \dfrac{3x - 2}{x - 1}\,\mathrm{d}x$.$h15sql$, 1, $h15sql$$3x - 2 = 3(x - 1) + 1$, dus $\dfrac{3x - 2}{x - 1} = 3 + \dfrac{1}{x - 1}$.$h15sql$),
  ('h15a_bepaald', 'h15a_bepaald', $h15sql$Bereken exact $\displaystyle\int_{2}^{4} \dfrac{3x - 2}{x - 1}\,\mathrm{d}x$.$h15sql$, 2, $h15sql$Een primitieve is $F(x) = 3x + \ln(x - 1)$.$h15sql$),
  ('h15a_bepaald', 'h15a_bepaald', $h15sql$Bereken exact $\displaystyle\int_{2}^{4} \dfrac{3x - 2}{x - 1}\,\mathrm{d}x$.$h15sql$, 3, $h15sql$$F(4) - F(2) = (12 + \ln(3)) - (6 + \ln(1)) = 6 + \ln(3)$.$h15sql$),
  ('h15a_oppervlakte', 'h15a_oppervlakte', $h15sql$Het vlakdeel $V$ wordt ingesloten door de grafiek van $f(x) = \dfrac{x + 3}{x + 1}$, de $x$-as en de lijnen $x = 0$ en $x = 1$. Bereken exact de oppervlakte van $V$.$h15sql$, 0, $h15sql$Hier spelen deel 1 en deel 2 van de driedeling: eerst het verhaal vertalen naar een integraal, dan die integraal exact uitrekenen. Op $[0, 1]$ ligt de grafiek boven de $x$-as, dus de oppervlakte is de integraal zelf.$h15sql$),
  ('h15a_oppervlakte', 'h15a_oppervlakte', $h15sql$Het vlakdeel $V$ wordt ingesloten door de grafiek van $f(x) = \dfrac{x + 3}{x + 1}$, de $x$-as en de lijnen $x = 0$ en $x = 1$. Bereken exact de oppervlakte van $V$.$h15sql$, 1, $h15sql$$O(V) = \displaystyle\int_{0}^{1} \dfrac{x + 3}{x + 1}\,\mathrm{d}x$ en $\dfrac{x + 3}{x + 1} = 1 + \dfrac{2}{x + 1}$.$h15sql$),
  ('h15a_oppervlakte', 'h15a_oppervlakte', $h15sql$Het vlakdeel $V$ wordt ingesloten door de grafiek van $f(x) = \dfrac{x + 3}{x + 1}$, de $x$-as en de lijnen $x = 0$ en $x = 1$. Bereken exact de oppervlakte van $V$.$h15sql$, 2, $h15sql$Een primitieve is $F(x) = x + 2\ln(x + 1)$.$h15sql$),
  ('h15a_oppervlakte', 'h15a_oppervlakte', $h15sql$Het vlakdeel $V$ wordt ingesloten door de grafiek van $f(x) = \dfrac{x + 3}{x + 1}$, de $x$-as en de lijnen $x = 0$ en $x = 1$. Bereken exact de oppervlakte van $V$.$h15sql$, 3, $h15sql$$F(1) - F(0) = 1 + 2\ln(2)$. De oppervlakte is $1 + 2\ln(2)$.$h15sql$),
  ('h15a_oppervlakte', 'h15a_oppervlakte', $h15sql$Het vlakdeel $V$ wordt ingesloten door de grafiek van $f(x) = \dfrac{2x + 4}{x + 1}$ en de lijn $y = 2$, tussen $x = 0$ en $x = 1$. Bereken exact de oppervlakte van $V$.$h15sql$, 0, $h15sql$Hier spelen deel 1 en deel 2 van de driedeling: eerst het verhaal vertalen naar een integraal, dan die integraal exact uitrekenen. Eerst zien welke grafiek boven ligt, dan het verschil integreren.$h15sql$),
  ('h15a_oppervlakte', 'h15a_oppervlakte', $h15sql$Het vlakdeel $V$ wordt ingesloten door de grafiek van $f(x) = \dfrac{2x + 4}{x + 1}$ en de lijn $y = 2$, tussen $x = 0$ en $x = 1$. Bereken exact de oppervlakte van $V$.$h15sql$, 1, $h15sql$$\dfrac{2x + 4}{x + 1} = 2 + \dfrac{2}{x + 1}$. Op $[0, 1]$ ligt $f$ dus boven $y = 2$. $O(V) = \displaystyle\int_{0}^{1} \dfrac{2}{x + 1}\,\mathrm{d}x$.$h15sql$),
  ('h15a_oppervlakte', 'h15a_oppervlakte', $h15sql$Het vlakdeel $V$ wordt ingesloten door de grafiek van $f(x) = \dfrac{2x + 4}{x + 1}$ en de lijn $y = 2$, tussen $x = 0$ en $x = 1$. Bereken exact de oppervlakte van $V$.$h15sql$, 2, $h15sql$Een primitieve is $F(x) = 2\ln(x + 1)$.$h15sql$),
  ('h15a_oppervlakte', 'h15a_oppervlakte', $h15sql$Het vlakdeel $V$ wordt ingesloten door de grafiek van $f(x) = \dfrac{2x + 4}{x + 1}$ en de lijn $y = 2$, tussen $x = 0$ en $x = 1$. Bereken exact de oppervlakte van $V$.$h15sql$, 3, $h15sql$$F(1) - F(0) = 2\ln(2)$. De oppervlakte is $2\ln(2)$.$h15sql$),
  ('h15a_oppervlakte', 'h15a_oppervlakte', $h15sql$Het vlakdeel $V$ wordt ingesloten door de grafiek van $f(x) = \dfrac{3x + 6}{x + 1}$, de $x$-as en de lijnen $x = 0$ en $x = 2$. Bereken exact de oppervlakte van $V$.$h15sql$, 0, $h15sql$Hier spelen deel 1 en deel 2 van de driedeling: eerst het verhaal vertalen naar een integraal, dan die integraal exact uitrekenen. Op $[0, 2]$ is $f(x) > 0$, dus de oppervlakte is de integraal.$h15sql$),
  ('h15a_oppervlakte', 'h15a_oppervlakte', $h15sql$Het vlakdeel $V$ wordt ingesloten door de grafiek van $f(x) = \dfrac{3x + 6}{x + 1}$, de $x$-as en de lijnen $x = 0$ en $x = 2$. Bereken exact de oppervlakte van $V$.$h15sql$, 1, $h15sql$$\dfrac{3x + 6}{x + 1} = 3 + \dfrac{3}{x + 1}$, dus $O(V) = \displaystyle\int_{0}^{2} \left(3 + \dfrac{3}{x + 1}\right)\,\mathrm{d}x$.$h15sql$),
  ('h15a_oppervlakte', 'h15a_oppervlakte', $h15sql$Het vlakdeel $V$ wordt ingesloten door de grafiek van $f(x) = \dfrac{3x + 6}{x + 1}$, de $x$-as en de lijnen $x = 0$ en $x = 2$. Bereken exact de oppervlakte van $V$.$h15sql$, 2, $h15sql$Een primitieve is $F(x) = 3x + 3\ln(x + 1)$.$h15sql$),
  ('h15a_oppervlakte', 'h15a_oppervlakte', $h15sql$Het vlakdeel $V$ wordt ingesloten door de grafiek van $f(x) = \dfrac{3x + 6}{x + 1}$, de $x$-as en de lijnen $x = 0$ en $x = 2$. Bereken exact de oppervlakte van $V$.$h15sql$, 3, $h15sql$$F(2) - F(0) = 6 + 3\ln(3)$. De oppervlakte is $6 + 3\ln(3)$.$h15sql$),
  ('h15a_oppervlakte', 'h15a_oppervlakte', $h15sql$Voor elke $a > 0$ sluit de grafiek van $f(x) = \dfrac{a}{x + 1}$ met de $x$-as en de lijnen $x = 0$ en $x = 1$ een vlakdeel $V_a$ in. Bereken exact de waarde van $a$ waarvoor de oppervlakte van $V_a$ gelijk is aan $2\ln(2)$.$h15sql$, 0, $h15sql$Hier spelen alle drie de delen: het verhaal wordt een integraal, die reken je exact uit, en met die uitkomst vind je de gevraagde waarde.$h15sql$),
  ('h15a_oppervlakte', 'h15a_oppervlakte', $h15sql$Voor elke $a > 0$ sluit de grafiek van $f(x) = \dfrac{a}{x + 1}$ met de $x$-as en de lijnen $x = 0$ en $x = 1$ een vlakdeel $V_a$ in. Bereken exact de waarde van $a$ waarvoor de oppervlakte van $V_a$ gelijk is aan $2\ln(2)$.$h15sql$, 1, $h15sql$Op $[0, 1]$ is $f(x) > 0$. $O(V_a) = \displaystyle\int_{0}^{1} \dfrac{a}{x + 1}\,\mathrm{d}x$.$h15sql$),
  ('h15a_oppervlakte', 'h15a_oppervlakte', $h15sql$Voor elke $a > 0$ sluit de grafiek van $f(x) = \dfrac{a}{x + 1}$ met de $x$-as en de lijnen $x = 0$ en $x = 1$ een vlakdeel $V_a$ in. Bereken exact de waarde van $a$ waarvoor de oppervlakte van $V_a$ gelijk is aan $2\ln(2)$.$h15sql$, 2, $h15sql$Zonder de $a$ is een primitieve $\ln(x + 1)$. Van $0$ tot $1$ geeft dat $\ln(2)$. Dus $O(V_a) = a\ln(2)$.$h15sql$),
  ('h15a_oppervlakte', 'h15a_oppervlakte', $h15sql$Voor elke $a > 0$ sluit de grafiek van $f(x) = \dfrac{a}{x + 1}$ met de $x$-as en de lijnen $x = 0$ en $x = 1$ een vlakdeel $V_a$ in. Bereken exact de waarde van $a$ waarvoor de oppervlakte van $V_a$ gelijk is aan $2\ln(2)$.$h15sql$, 3, $h15sql$Deel 3: $a\ln(2) = 2\ln(2)$, dus $a = 2$.$h15sql$),
  ('h15a_oppervlakte', 'h15a_oppervlakte', $h15sql$Het vlakdeel $V$ wordt ingesloten door de grafiek van $f(x) = \dfrac{x + 5}{x + 1}$ en de lijn $y = 1$, tussen $x = 0$ en $x = 3$. Bereken exact de oppervlakte van $V$.$h15sql$, 0, $h15sql$Hier spelen deel 1 en deel 2 van de driedeling: eerst het verhaal vertalen naar een integraal, dan die integraal exact uitrekenen. Het verschil van de twee grafieken is de integrand.$h15sql$),
  ('h15a_oppervlakte', 'h15a_oppervlakte', $h15sql$Het vlakdeel $V$ wordt ingesloten door de grafiek van $f(x) = \dfrac{x + 5}{x + 1}$ en de lijn $y = 1$, tussen $x = 0$ en $x = 3$. Bereken exact de oppervlakte van $V$.$h15sql$, 1, $h15sql$$\dfrac{x + 5}{x + 1} = 1 + \dfrac{4}{x + 1}$. Op $[0, 3]$ ligt $f$ boven $y = 1$. $O(V) = \displaystyle\int_{0}^{3} \dfrac{4}{x + 1}\,\mathrm{d}x$.$h15sql$),
  ('h15a_oppervlakte', 'h15a_oppervlakte', $h15sql$Het vlakdeel $V$ wordt ingesloten door de grafiek van $f(x) = \dfrac{x + 5}{x + 1}$ en de lijn $y = 1$, tussen $x = 0$ en $x = 3$. Bereken exact de oppervlakte van $V$.$h15sql$, 2, $h15sql$Een primitieve is $F(x) = 4\ln(x + 1)$.$h15sql$),
  ('h15a_oppervlakte', 'h15a_oppervlakte', $h15sql$Het vlakdeel $V$ wordt ingesloten door de grafiek van $f(x) = \dfrac{x + 5}{x + 1}$ en de lijn $y = 1$, tussen $x = 0$ en $x = 3$. Bereken exact de oppervlakte van $V$.$h15sql$, 3, $h15sql$$F(3) - F(0) = 4\ln(4) = 8\ln(2)$. De oppervlakte is $8\ln(2)$.$h15sql$),
  ('h15a_oppervlakte', 'h15a_oppervlakte', $h15sql$Het vlakdeel $V$ wordt ingesloten door de grafiek van $f(x) = \dfrac{4x + 2}{x + 2}$, de $x$-as en de lijnen $x = 0$ en $x = 2$. Bereken exact de oppervlakte van $V$.$h15sql$, 0, $h15sql$Hier spelen deel 1 en deel 2 van de driedeling: eerst het verhaal vertalen naar een integraal, dan die integraal exact uitrekenen. Eerst controleren dat de grafiek op dit stuk boven de $x$-as ligt, dan integreren.$h15sql$),
  ('h15a_oppervlakte', 'h15a_oppervlakte', $h15sql$Het vlakdeel $V$ wordt ingesloten door de grafiek van $f(x) = \dfrac{4x + 2}{x + 2}$, de $x$-as en de lijnen $x = 0$ en $x = 2$. Bereken exact de oppervlakte van $V$.$h15sql$, 1, $h15sql$$4x + 2 = 4(x + 2) - 6$, dus $f(x) = 4 - \dfrac{6}{x + 2}$. Op $[0, 2]$ is $f(x) > 0$. $O(V) = \displaystyle\int_{0}^{2} \left(4 - \dfrac{6}{x + 2}\right)\,\mathrm{d}x$.$h15sql$),
  ('h15a_oppervlakte', 'h15a_oppervlakte', $h15sql$Het vlakdeel $V$ wordt ingesloten door de grafiek van $f(x) = \dfrac{4x + 2}{x + 2}$, de $x$-as en de lijnen $x = 0$ en $x = 2$. Bereken exact de oppervlakte van $V$.$h15sql$, 2, $h15sql$Een primitieve is $F(x) = 4x - 6\ln(x + 2)$.$h15sql$),
  ('h15a_oppervlakte', 'h15a_oppervlakte', $h15sql$Het vlakdeel $V$ wordt ingesloten door de grafiek van $f(x) = \dfrac{4x + 2}{x + 2}$, de $x$-as en de lijnen $x = 0$ en $x = 2$. Bereken exact de oppervlakte van $V$.$h15sql$, 3, $h15sql$$F(2) - F(0) = (8 - 6\ln(4)) - (-6\ln(2)) = 8 - 12\ln(2) + 6\ln(2) = 8 - 6\ln(2)$.$h15sql$),
  ('h15a_oppervlakte', 'h15a_oppervlakte', $h15sql$Voor elke $p > 0$ sluit de grafiek van $f(x) = \dfrac{3}{x + 2}$ met de $x$-as en de lijnen $x = 0$ en $x = p$ een vlakdeel $V_p$ in. Bereken exact de waarde van $p$ waarvoor de oppervlakte van $V_p$ gelijk is aan $\ln(8)$.$h15sql$, 0, $h15sql$Hier spelen alle drie de delen: het verhaal wordt een integraal, die reken je exact uit, en met die uitkomst vind je de gevraagde waarde.$h15sql$),
  ('h15a_oppervlakte', 'h15a_oppervlakte', $h15sql$Voor elke $p > 0$ sluit de grafiek van $f(x) = \dfrac{3}{x + 2}$ met de $x$-as en de lijnen $x = 0$ en $x = p$ een vlakdeel $V_p$ in. Bereken exact de waarde van $p$ waarvoor de oppervlakte van $V_p$ gelijk is aan $\ln(8)$.$h15sql$, 1, $h15sql$Op $[0, p]$ is $f(x) > 0$. $O(V_p) = \displaystyle\int_{0}^{p} \dfrac{3}{x + 2}\,\mathrm{d}x$.$h15sql$),
  ('h15a_oppervlakte', 'h15a_oppervlakte', $h15sql$Voor elke $p > 0$ sluit de grafiek van $f(x) = \dfrac{3}{x + 2}$ met de $x$-as en de lijnen $x = 0$ en $x = p$ een vlakdeel $V_p$ in. Bereken exact de waarde van $p$ waarvoor de oppervlakte van $V_p$ gelijk is aan $\ln(8)$.$h15sql$, 2, $h15sql$Een primitieve is $3\ln(x + 2)$. Dus $O(V_p) = 3\ln(p + 2) - 3\ln(2) = 3\ln\left(\dfrac{p + 2}{2}\right)$.$h15sql$),
  ('h15a_oppervlakte', 'h15a_oppervlakte', $h15sql$Voor elke $p > 0$ sluit de grafiek van $f(x) = \dfrac{3}{x + 2}$ met de $x$-as en de lijnen $x = 0$ en $x = p$ een vlakdeel $V_p$ in. Bereken exact de waarde van $p$ waarvoor de oppervlakte van $V_p$ gelijk is aan $\ln(8)$.$h15sql$, 3, $h15sql$Deel 3: $3\ln\left(\dfrac{p + 2}{2}\right) = \ln(8) = 3\ln(2)$. Dus $\dfrac{p + 2}{2} = 2$, en $p = 2$.$h15sql$),
  ('h15a_oppervlakte', 'h15a_oppervlakte', $h15sql$Het vlakdeel $V$ wordt ingesloten door de grafieken van $f(x) = \dfrac{2x + 1}{x + 1}$ en $g(x) = \dfrac{x + 2}{x + 1}$ en de lijnen $x = 0$ en $x = 1$. Bereken exact de oppervlakte van $V$.$h15sql$, 0, $h15sql$Hier spelen deel 1 en deel 2 van de driedeling: eerst het verhaal vertalen naar een integraal, dan die integraal exact uitrekenen. Eerst welke grafiek boven ligt, dan het verschil integreren.$h15sql$),
  ('h15a_oppervlakte', 'h15a_oppervlakte', $h15sql$Het vlakdeel $V$ wordt ingesloten door de grafieken van $f(x) = \dfrac{2x + 1}{x + 1}$ en $g(x) = \dfrac{x + 2}{x + 1}$ en de lijnen $x = 0$ en $x = 1$. Bereken exact de oppervlakte van $V$.$h15sql$, 1, $h15sql$$f(x) = 2 - \dfrac{1}{x + 1}$ en $g(x) = 1 + \dfrac{1}{x + 1}$. Dus $g(x) - f(x) = \dfrac{2}{x + 1} - 1$. Op $[0, 1]$ is dat positief, dus $g$ ligt boven. $O(V) = \displaystyle\int_{0}^{1} \left(\dfrac{2}{x + 1} - 1\right)\,\mathrm{d}x$.$h15sql$),
  ('h15a_oppervlakte', 'h15a_oppervlakte', $h15sql$Het vlakdeel $V$ wordt ingesloten door de grafieken van $f(x) = \dfrac{2x + 1}{x + 1}$ en $g(x) = \dfrac{x + 2}{x + 1}$ en de lijnen $x = 0$ en $x = 1$. Bereken exact de oppervlakte van $V$.$h15sql$, 2, $h15sql$Een primitieve is $F(x) = 2\ln(x + 1) - x$.$h15sql$),
  ('h15a_oppervlakte', 'h15a_oppervlakte', $h15sql$Het vlakdeel $V$ wordt ingesloten door de grafieken van $f(x) = \dfrac{2x + 1}{x + 1}$ en $g(x) = \dfrac{x + 2}{x + 1}$ en de lijnen $x = 0$ en $x = 1$. Bereken exact de oppervlakte van $V$.$h15sql$, 3, $h15sql$$F(1) - F(0) = 2\ln(2) - 1$. De oppervlakte is $2\ln(2) - 1$.$h15sql$),
  ('h15b_verhouding', 'h15b_verhouding', $h15sql$De grafiek van $f(x) = x$ snijdt de rechthoek met hoekpunten $(0, 0)$, $(4, 0)$, $(4, 4)$ en $(0, 4)$ in een onderste vlakdeel $V$ en een bovenste vlakdeel $W$. Bereken de verhouding $O(V) : O(W)$.$h15sql$, 0, $h15sql$Hier spelen deel 1 en deel 2 van de driedeling: eerst het verhaal vertalen naar een integraal, dan die integraal exact uitrekenen. $V$ ligt onder de lijn, $W$ is de rest van de rechthoek.$h15sql$),
  ('h15b_verhouding', 'h15b_verhouding', $h15sql$De grafiek van $f(x) = x$ snijdt de rechthoek met hoekpunten $(0, 0)$, $(4, 0)$, $(4, 4)$ en $(0, 4)$ in een onderste vlakdeel $V$ en een bovenste vlakdeel $W$. Bereken de verhouding $O(V) : O(W)$.$h15sql$, 1, $h15sql$$O(V) = \displaystyle\int_{0}^{4} x\,\mathrm{d}x$. De rechthoek heeft oppervlakte $4 \cdot 4 = 16$, en $O(W) = 16 - O(V)$.$h15sql$),
  ('h15b_verhouding', 'h15b_verhouding', $h15sql$De grafiek van $f(x) = x$ snijdt de rechthoek met hoekpunten $(0, 0)$, $(4, 0)$, $(4, 4)$ en $(0, 4)$ in een onderste vlakdeel $V$ en een bovenste vlakdeel $W$. Bereken de verhouding $O(V) : O(W)$.$h15sql$, 2, $h15sql$Een primitieve is $\dfrac{1}{2}x^{2}$. Dus $O(V) = 8$ en $O(W) = 8$.$h15sql$),
  ('h15b_verhouding', 'h15b_verhouding', $h15sql$De grafiek van $f(x) = x$ snijdt de rechthoek met hoekpunten $(0, 0)$, $(4, 0)$, $(4, 4)$ en $(0, 4)$ in een onderste vlakdeel $V$ en een bovenste vlakdeel $W$. Bereken de verhouding $O(V) : O(W)$.$h15sql$, 3, $h15sql$$O(V) : O(W) = 8 : 8 = 1 : 1$.$h15sql$),
  ('h15b_verhouding', 'h15b_verhouding', $h15sql$De grafiek van $f(x) = x^{2}$ en de lijn $y = 9$ sluiten op $[0, 3]$ twee vlakdelen in: $V$ onder de parabool en $W$ tussen de parabool en de lijn $y = 9$. Bereken de verhouding $O(V) : O(W)$.$h15sql$, 0, $h15sql$Hier spelen deel 1 en deel 2 van de driedeling: eerst het verhaal vertalen naar een integraal, dan die integraal exact uitrekenen. $V$ is de integraal van $x^{2}$. $W$ is de rechthoek minus $V$.$h15sql$),
  ('h15b_verhouding', 'h15b_verhouding', $h15sql$De grafiek van $f(x) = x^{2}$ en de lijn $y = 9$ sluiten op $[0, 3]$ twee vlakdelen in: $V$ onder de parabool en $W$ tussen de parabool en de lijn $y = 9$. Bereken de verhouding $O(V) : O(W)$.$h15sql$, 1, $h15sql$$O(V) = \displaystyle\int_{0}^{3} x^{2}\,\mathrm{d}x$. De rechthoek heeft oppervlakte $3 \cdot 9 = 27$.$h15sql$),
  ('h15b_verhouding', 'h15b_verhouding', $h15sql$De grafiek van $f(x) = x^{2}$ en de lijn $y = 9$ sluiten op $[0, 3]$ twee vlakdelen in: $V$ onder de parabool en $W$ tussen de parabool en de lijn $y = 9$. Bereken de verhouding $O(V) : O(W)$.$h15sql$, 2, $h15sql$Een primitieve is $\dfrac{1}{3}x^{3}$. Dus $O(V) = 9$ en $O(W) = 18$.$h15sql$),
  ('h15b_verhouding', 'h15b_verhouding', $h15sql$De grafiek van $f(x) = x^{2}$ en de lijn $y = 9$ sluiten op $[0, 3]$ twee vlakdelen in: $V$ onder de parabool en $W$ tussen de parabool en de lijn $y = 9$. Bereken de verhouding $O(V) : O(W)$.$h15sql$, 3, $h15sql$$O(V) : O(W) = 9 : 18 = 1 : 2$.$h15sql$),
  ('h15b_verhouding', 'h15b_verhouding', $h15sql$De grafiek van $f(x) = \sqrt{x}$ en de lijn $y = 3$ sluiten op $[0, 9]$ twee vlakdelen in: $V$ onder de grafiek en $W$ tussen de grafiek en $y = 3$. Bereken de verhouding $O(V) : O(W)$.$h15sql$, 0, $h15sql$Hier spelen deel 1 en deel 2 van de driedeling: eerst het verhaal vertalen naar een integraal, dan die integraal exact uitrekenen. Op $[0, 9]$ loopt de grafiek van $0$ tot $3$, dus de lijn $y = 3$ sluit er precies op aan.$h15sql$),
  ('h15b_verhouding', 'h15b_verhouding', $h15sql$De grafiek van $f(x) = \sqrt{x}$ en de lijn $y = 3$ sluiten op $[0, 9]$ twee vlakdelen in: $V$ onder de grafiek en $W$ tussen de grafiek en $y = 3$. Bereken de verhouding $O(V) : O(W)$.$h15sql$, 1, $h15sql$$O(V) = \displaystyle\int_{0}^{9} \sqrt{x}\,\mathrm{d}x$. De rechthoek heeft oppervlakte $9 \cdot 3 = 27$.$h15sql$),
  ('h15b_verhouding', 'h15b_verhouding', $h15sql$De grafiek van $f(x) = \sqrt{x}$ en de lijn $y = 3$ sluiten op $[0, 9]$ twee vlakdelen in: $V$ onder de grafiek en $W$ tussen de grafiek en $y = 3$. Bereken de verhouding $O(V) : O(W)$.$h15sql$, 2, $h15sql$Een primitieve van $\sqrt{x}$ is $\dfrac{2}{3}x^{3/2}$. Dus $O(V) = \dfrac{2}{3} \cdot 27 = 18$ en $O(W) = 9$.$h15sql$),
  ('h15b_verhouding', 'h15b_verhouding', $h15sql$De grafiek van $f(x) = \sqrt{x}$ en de lijn $y = 3$ sluiten op $[0, 9]$ twee vlakdelen in: $V$ onder de grafiek en $W$ tussen de grafiek en $y = 3$. Bereken de verhouding $O(V) : O(W)$.$h15sql$, 3, $h15sql$$O(V) : O(W) = 18 : 9 = 2 : 1$.$h15sql$),
  ('h15b_verhouding', 'h15b_verhouding', $h15sql$De grafiek van $f(x) = x^{3}$ en de lijn $y = 8$ sluiten op $[0, 2]$ twee vlakdelen in: $V$ onder de grafiek en $W$ tussen de grafiek en $y = 8$. Bereken de verhouding $O(V) : O(W)$.$h15sql$, 0, $h15sql$Hier spelen deel 1 en deel 2 van de driedeling: eerst het verhaal vertalen naar een integraal, dan die integraal exact uitrekenen. $V$ is de integraal van $x^{3}$. $W$ is de rest van de rechthoek.$h15sql$),
  ('h15b_verhouding', 'h15b_verhouding', $h15sql$De grafiek van $f(x) = x^{3}$ en de lijn $y = 8$ sluiten op $[0, 2]$ twee vlakdelen in: $V$ onder de grafiek en $W$ tussen de grafiek en $y = 8$. Bereken de verhouding $O(V) : O(W)$.$h15sql$, 1, $h15sql$$O(V) = \displaystyle\int_{0}^{2} x^{3}\,\mathrm{d}x$. De rechthoek heeft oppervlakte $2 \cdot 8 = 16$.$h15sql$),
  ('h15b_verhouding', 'h15b_verhouding', $h15sql$De grafiek van $f(x) = x^{3}$ en de lijn $y = 8$ sluiten op $[0, 2]$ twee vlakdelen in: $V$ onder de grafiek en $W$ tussen de grafiek en $y = 8$. Bereken de verhouding $O(V) : O(W)$.$h15sql$, 2, $h15sql$Een primitieve is $\dfrac{1}{4}x^{4}$. Dus $O(V) = 4$ en $O(W) = 12$.$h15sql$),
  ('h15b_verhouding', 'h15b_verhouding', $h15sql$De grafiek van $f(x) = x^{3}$ en de lijn $y = 8$ sluiten op $[0, 2]$ twee vlakdelen in: $V$ onder de grafiek en $W$ tussen de grafiek en $y = 8$. Bereken de verhouding $O(V) : O(W)$.$h15sql$, 3, $h15sql$$O(V) : O(W) = 4 : 12 = 1 : 3$.$h15sql$),
  ('h15b_verhouding', 'h15b_verhouding', $h15sql$De grafieken van $f(x) = x$ en $g(x) = x^{2}$ sluiten op $[0, 1]$ het vlakdeel $V$ in. Het vlakdeel $W$ ligt onder $g$ op datzelfde interval. Bereken de verhouding $O(V) : O(W)$.$h15sql$, 0, $h15sql$Hier spelen deel 1 en deel 2 van de driedeling: eerst het verhaal vertalen naar een integraal, dan die integraal exact uitrekenen. Op $[0, 1]$ ligt $y = x$ boven $y = x^{2}$.$h15sql$),
  ('h15b_verhouding', 'h15b_verhouding', $h15sql$De grafieken van $f(x) = x$ en $g(x) = x^{2}$ sluiten op $[0, 1]$ het vlakdeel $V$ in. Het vlakdeel $W$ ligt onder $g$ op datzelfde interval. Bereken de verhouding $O(V) : O(W)$.$h15sql$, 1, $h15sql$$O(V) = \displaystyle\int_{0}^{1} (x - x^{2})\,\mathrm{d}x$ en $O(W) = \displaystyle\int_{0}^{1} x^{2}\,\mathrm{d}x$.$h15sql$),
  ('h15b_verhouding', 'h15b_verhouding', $h15sql$De grafieken van $f(x) = x$ en $g(x) = x^{2}$ sluiten op $[0, 1]$ het vlakdeel $V$ in. Het vlakdeel $W$ ligt onder $g$ op datzelfde interval. Bereken de verhouding $O(V) : O(W)$.$h15sql$, 2, $h15sql$Een primitieve van $x - x^{2}$ is $\dfrac{1}{2}x^{2} - \dfrac{1}{3}x^{3}$. Dus $O(V) = \dfrac{1}{2} - \dfrac{1}{3} = \dfrac{1}{6}$. En $O(W) = \dfrac{1}{3}$.$h15sql$),
  ('h15b_verhouding', 'h15b_verhouding', $h15sql$De grafieken van $f(x) = x$ en $g(x) = x^{2}$ sluiten op $[0, 1]$ het vlakdeel $V$ in. Het vlakdeel $W$ ligt onder $g$ op datzelfde interval. Bereken de verhouding $O(V) : O(W)$.$h15sql$, 3, $h15sql$$O(V) : O(W) = \dfrac{1}{6} : \dfrac{1}{3} = 1 : 2$.$h15sql$),
  ('h15b_verhouding', 'h15b_verhouding', $h15sql$De grafieken van $f(x) = \sqrt{x}$ en $g(x) = x$ sluiten op $[0, 1]$ het vlakdeel $V$ in. Het vlakdeel $W$ ligt onder $g$ op datzelfde interval. Bereken de verhouding $O(V) : O(W)$.$h15sql$, 0, $h15sql$Hier spelen deel 1 en deel 2 van de driedeling: eerst het verhaal vertalen naar een integraal, dan die integraal exact uitrekenen. Op $[0, 1]$ ligt $sqrt{x}$ boven $y = x$.$h15sql$),
  ('h15b_verhouding', 'h15b_verhouding', $h15sql$De grafieken van $f(x) = \sqrt{x}$ en $g(x) = x$ sluiten op $[0, 1]$ het vlakdeel $V$ in. Het vlakdeel $W$ ligt onder $g$ op datzelfde interval. Bereken de verhouding $O(V) : O(W)$.$h15sql$, 1, $h15sql$$O(V) = \displaystyle\int_{0}^{1} \left(\sqrt{x} - x\right)\,\mathrm{d}x$ en $O(W) = \displaystyle\int_{0}^{1} x\,\mathrm{d}x = \dfrac{1}{2}$.$h15sql$),
  ('h15b_verhouding', 'h15b_verhouding', $h15sql$De grafieken van $f(x) = \sqrt{x}$ en $g(x) = x$ sluiten op $[0, 1]$ het vlakdeel $V$ in. Het vlakdeel $W$ ligt onder $g$ op datzelfde interval. Bereken de verhouding $O(V) : O(W)$.$h15sql$, 2, $h15sql$Een primitieve van $\sqrt{x} - x$ is $\dfrac{2}{3}x^{3/2} - \dfrac{1}{2}x^{2}$. Dus $O(V) = \dfrac{2}{3} - \dfrac{1}{2} = \dfrac{1}{6}$.$h15sql$),
  ('h15b_verhouding', 'h15b_verhouding', $h15sql$De grafieken van $f(x) = \sqrt{x}$ en $g(x) = x$ sluiten op $[0, 1]$ het vlakdeel $V$ in. Het vlakdeel $W$ ligt onder $g$ op datzelfde interval. Bereken de verhouding $O(V) : O(W)$.$h15sql$, 3, $h15sql$$O(V) : O(W) = \dfrac{1}{6} : \dfrac{1}{2} = 1 : 3$.$h15sql$),
  ('h15b_verhouding', 'h15b_verhouding', $h15sql$Voor elke $a > 0$ deelt de lijn $y = ax$ de rechthoek met hoekpunten $(0, 0)$, $(1, 0)$, $(1, a)$ en $(0, a)$ in een onderste vlakdeel $V$ en een bovenste vlakdeel $W$. Bereken de verhouding $O(V) : O(W)$. Die verhouding hangt niet van $a$ af.$h15sql$, 0, $h15sql$Hier spelen deel 1 en deel 2 van de driedeling: eerst het verhaal vertalen naar een integraal, dan die integraal exact uitrekenen. De factor $a$ komt in beide oppervlakten voor en valt in de verhouding weg.$h15sql$),
  ('h15b_verhouding', 'h15b_verhouding', $h15sql$Voor elke $a > 0$ deelt de lijn $y = ax$ de rechthoek met hoekpunten $(0, 0)$, $(1, 0)$, $(1, a)$ en $(0, a)$ in een onderste vlakdeel $V$ en een bovenste vlakdeel $W$. Bereken de verhouding $O(V) : O(W)$. Die verhouding hangt niet van $a$ af.$h15sql$, 1, $h15sql$$O(V) = \displaystyle\int_{0}^{1} ax\,\mathrm{d}x$. De rechthoek heeft oppervlakte $1 \cdot a = a$, dus $O(W) = a - O(V)$.$h15sql$),
  ('h15b_verhouding', 'h15b_verhouding', $h15sql$Voor elke $a > 0$ deelt de lijn $y = ax$ de rechthoek met hoekpunten $(0, 0)$, $(1, 0)$, $(1, a)$ en $(0, a)$ in een onderste vlakdeel $V$ en een bovenste vlakdeel $W$. Bereken de verhouding $O(V) : O(W)$. Die verhouding hangt niet van $a$ af.$h15sql$, 2, $h15sql$Een primitieve van $x$ is $\dfrac{1}{2}x^{2}$, dus de integraal van $x$ van $0$ tot $1$ is $\dfrac{1}{2}$. Dus $O(V) = \dfrac{1}{2}a$ en $O(W) = \dfrac{1}{2}a$.$h15sql$),
  ('h15b_verhouding', 'h15b_verhouding', $h15sql$Voor elke $a > 0$ deelt de lijn $y = ax$ de rechthoek met hoekpunten $(0, 0)$, $(1, 0)$, $(1, a)$ en $(0, a)$ in een onderste vlakdeel $V$ en een bovenste vlakdeel $W$. Bereken de verhouding $O(V) : O(W)$. Die verhouding hangt niet van $a$ af.$h15sql$, 3, $h15sql$$O(V) : O(W) = 1 : 1$, voor elke $a > 0$.$h15sql$),
  ('h15b_verhouding', 'h15b_verhouding', $h15sql$De grafiek van $f(x) = 6x - x^{2}$ en de $x$-as sluiten op $[0, 6]$ een vlakdeel in. De lijn $x = 3$ deelt dat vlakdeel in $V$ links en $W$ rechts. Bereken de verhouding $O(V) : O(W)$.$h15sql$, 0, $h15sql$Hier spelen deel 1 en deel 2 van de driedeling: eerst het verhaal vertalen naar een integraal, dan die integraal exact uitrekenen. De parabool is symmetrisch om $x = 3$, en de lijn $x = 3$ is precies die as.$h15sql$),
  ('h15b_verhouding', 'h15b_verhouding', $h15sql$De grafiek van $f(x) = 6x - x^{2}$ en de $x$-as sluiten op $[0, 6]$ een vlakdeel in. De lijn $x = 3$ deelt dat vlakdeel in $V$ links en $W$ rechts. Bereken de verhouding $O(V) : O(W)$.$h15sql$, 1, $h15sql$$O(V) = \displaystyle\int_{0}^{3} (6x - x^{2})\,\mathrm{d}x$. Het hele vlakdeel loopt van $0$ tot $6$.$h15sql$),
  ('h15b_verhouding', 'h15b_verhouding', $h15sql$De grafiek van $f(x) = 6x - x^{2}$ en de $x$-as sluiten op $[0, 6]$ een vlakdeel in. De lijn $x = 3$ deelt dat vlakdeel in $V$ links en $W$ rechts. Bereken de verhouding $O(V) : O(W)$.$h15sql$, 2, $h15sql$Een primitieve is $3x^{2} - \dfrac{1}{3}x^{3}$. Dus $O(V) = 27 - 9 = 18$. Het hele vlakdeel heeft oppervlakte $36$, dus $O(W) = 18$.$h15sql$),
  ('h15b_verhouding', 'h15b_verhouding', $h15sql$De grafiek van $f(x) = 6x - x^{2}$ en de $x$-as sluiten op $[0, 6]$ een vlakdeel in. De lijn $x = 3$ deelt dat vlakdeel in $V$ links en $W$ rechts. Bereken de verhouding $O(V) : O(W)$.$h15sql$, 3, $h15sql$$O(V) : O(W) = 18 : 18 = 1 : 1$.$h15sql$),
  ('h15b_parameter', 'h15b_parameter', $h15sql$Voor elke $p > 0$ sluit de grafiek van $f(x) = x$ met de $x$-as en de lijn $x = p$ een vlakdeel $V_p$ in. Bereken exact de waarde van $p$ waarvoor de oppervlakte van $V_p$ gelijk is aan $8$.$h15sql$, 0, $h15sql$Hier spelen alle drie de delen: het verhaal wordt een integraal, die reken je exact uit, en met die uitkomst vind je de gevraagde waarde.$h15sql$),
  ('h15b_parameter', 'h15b_parameter', $h15sql$Voor elke $p > 0$ sluit de grafiek van $f(x) = x$ met de $x$-as en de lijn $x = p$ een vlakdeel $V_p$ in. Bereken exact de waarde van $p$ waarvoor de oppervlakte van $V_p$ gelijk is aan $8$.$h15sql$, 1, $h15sql$$O(V_p) = \displaystyle\int_{0}^{p} x\,\mathrm{d}x$.$h15sql$),
  ('h15b_parameter', 'h15b_parameter', $h15sql$Voor elke $p > 0$ sluit de grafiek van $f(x) = x$ met de $x$-as en de lijn $x = p$ een vlakdeel $V_p$ in. Bereken exact de waarde van $p$ waarvoor de oppervlakte van $V_p$ gelijk is aan $8$.$h15sql$, 2, $h15sql$Een primitieve is $\dfrac{1}{2}x^{2}$. Dus $O(V_p) = \dfrac{1}{2}p^{2}$.$h15sql$),
  ('h15b_parameter', 'h15b_parameter', $h15sql$Voor elke $p > 0$ sluit de grafiek van $f(x) = x$ met de $x$-as en de lijn $x = p$ een vlakdeel $V_p$ in. Bereken exact de waarde van $p$ waarvoor de oppervlakte van $V_p$ gelijk is aan $8$.$h15sql$, 3, $h15sql$Deel 3: $\dfrac{1}{2}p^{2} = 8$, dus $p^{2} = 16$. Omdat $p > 0$ is $p = 4$.$h15sql$),
  ('h15b_parameter', 'h15b_parameter', $h15sql$Voor elke $p > 0$ sluit de grafiek van $f(x) = x^{2}$ met de $x$-as en de lijn $x = p$ een vlakdeel $V_p$ in. Bereken exact de waarde van $p$ waarvoor de oppervlakte van $V_p$ gelijk is aan $9$.$h15sql$, 0, $h15sql$Hier spelen alle drie de delen: het verhaal wordt een integraal, die reken je exact uit, en met die uitkomst vind je de gevraagde waarde.$h15sql$),
  ('h15b_parameter', 'h15b_parameter', $h15sql$Voor elke $p > 0$ sluit de grafiek van $f(x) = x^{2}$ met de $x$-as en de lijn $x = p$ een vlakdeel $V_p$ in. Bereken exact de waarde van $p$ waarvoor de oppervlakte van $V_p$ gelijk is aan $9$.$h15sql$, 1, $h15sql$$O(V_p) = \displaystyle\int_{0}^{p} x^{2}\,\mathrm{d}x$.$h15sql$),
  ('h15b_parameter', 'h15b_parameter', $h15sql$Voor elke $p > 0$ sluit de grafiek van $f(x) = x^{2}$ met de $x$-as en de lijn $x = p$ een vlakdeel $V_p$ in. Bereken exact de waarde van $p$ waarvoor de oppervlakte van $V_p$ gelijk is aan $9$.$h15sql$, 2, $h15sql$Een primitieve is $\dfrac{1}{3}x^{3}$. Dus $O(V_p) = \dfrac{1}{3}p^{3}$.$h15sql$),
  ('h15b_parameter', 'h15b_parameter', $h15sql$Voor elke $p > 0$ sluit de grafiek van $f(x) = x^{2}$ met de $x$-as en de lijn $x = p$ een vlakdeel $V_p$ in. Bereken exact de waarde van $p$ waarvoor de oppervlakte van $V_p$ gelijk is aan $9$.$h15sql$, 3, $h15sql$Deel 3: $\dfrac{1}{3}p^{3} = 9$, dus $p^{3} = 27$ en $p = 3$.$h15sql$),
  ('h15b_parameter', 'h15b_parameter', $h15sql$Voor elke $p > 0$ sluit de grafiek van $f(x) = \sqrt{x}$ met de $x$-as en de lijn $x = p$ een vlakdeel $V_p$ in. Bereken exact de waarde van $p$ waarvoor de oppervlakte van $V_p$ gelijk is aan $\dfrac{16}{3}$.$h15sql$, 0, $h15sql$Hier spelen alle drie de delen: het verhaal wordt een integraal, die reken je exact uit, en met die uitkomst vind je de gevraagde waarde.$h15sql$),
  ('h15b_parameter', 'h15b_parameter', $h15sql$Voor elke $p > 0$ sluit de grafiek van $f(x) = \sqrt{x}$ met de $x$-as en de lijn $x = p$ een vlakdeel $V_p$ in. Bereken exact de waarde van $p$ waarvoor de oppervlakte van $V_p$ gelijk is aan $\dfrac{16}{3}$.$h15sql$, 1, $h15sql$$O(V_p) = \displaystyle\int_{0}^{p} \sqrt{x}\,\mathrm{d}x$.$h15sql$),
  ('h15b_parameter', 'h15b_parameter', $h15sql$Voor elke $p > 0$ sluit de grafiek van $f(x) = \sqrt{x}$ met de $x$-as en de lijn $x = p$ een vlakdeel $V_p$ in. Bereken exact de waarde van $p$ waarvoor de oppervlakte van $V_p$ gelijk is aan $\dfrac{16}{3}$.$h15sql$, 2, $h15sql$Een primitieve is $\dfrac{2}{3}x^{3/2}$. Dus $O(V_p) = \dfrac{2}{3}p^{3/2}$.$h15sql$),
  ('h15b_parameter', 'h15b_parameter', $h15sql$Voor elke $p > 0$ sluit de grafiek van $f(x) = \sqrt{x}$ met de $x$-as en de lijn $x = p$ een vlakdeel $V_p$ in. Bereken exact de waarde van $p$ waarvoor de oppervlakte van $V_p$ gelijk is aan $\dfrac{16}{3}$.$h15sql$, 3, $h15sql$Deel 3: $\dfrac{2}{3}p^{3/2} = \dfrac{16}{3}$, dus $p^{3/2} = 8$. Dan $p = 4$, want $4^{3/2} = 8$.$h15sql$),
  ('h15b_parameter', 'h15b_parameter', $h15sql$Voor elke $a$ met $0 < a < 4$ zijn gegeven $f(x) = 4 - x^{2}$ en $g(x) = a - x^{2}$. Het vlakdeel $V$ ligt tussen de grafieken van $f$ en $g$. Het vlakdeel $W$ ligt onder de grafiek van $g$, tot aan de $x$-as. Bereken exact de waarde van $a$ waarvoor $O(V) = O(W)$.$h15sql$, 0, $h15sql$Hier spelen alle drie de delen: het verhaal wordt een integraal, die reken je exact uit, en met die uitkomst vind je de gevraagde waarde.$h15sql$),
  ('h15b_parameter', 'h15b_parameter', $h15sql$Voor elke $a$ met $0 < a < 4$ zijn gegeven $f(x) = 4 - x^{2}$ en $g(x) = a - x^{2}$. Het vlakdeel $V$ ligt tussen de grafieken van $f$ en $g$. Het vlakdeel $W$ ligt onder de grafiek van $g$, tot aan de $x$-as. Bereken exact de waarde van $a$ waarvoor $O(V) = O(W)$.$h15sql$, 1, $h15sql$$g$ snijdt de $x$-as bij $x = \pm\sqrt{a}$. Tussen die punten is $f(x) - g(x) = 4 - a$. Dus $O(V) = 2\sqrt{a}\,(4 - a)$. En $O(W) = \displaystyle\int_{-\sqrt{a}}^{\sqrt{a}} (a - x^{2})\,\mathrm{d}x = \dfrac{4}{3}a^{3/2}$.$h15sql$),
  ('h15b_parameter', 'h15b_parameter', $h15sql$Voor elke $a$ met $0 < a < 4$ zijn gegeven $f(x) = 4 - x^{2}$ en $g(x) = a - x^{2}$. Het vlakdeel $V$ ligt tussen de grafieken van $f$ en $g$. Het vlakdeel $W$ ligt onder de grafiek van $g$, tot aan de $x$-as. Bereken exact de waarde van $a$ waarvoor $O(V) = O(W)$.$h15sql$, 2, $h15sql$Stel $O(V) = O(W)$: $2\sqrt{a}\,(4 - a) = \dfrac{4}{3}a^{3/2}$. Deel door $2\sqrt{a}$, dat mag omdat $a > 0$: $4 - a = \dfrac{2}{3}a$.$h15sql$),
  ('h15b_parameter', 'h15b_parameter', $h15sql$Voor elke $a$ met $0 < a < 4$ zijn gegeven $f(x) = 4 - x^{2}$ en $g(x) = a - x^{2}$. Het vlakdeel $V$ ligt tussen de grafieken van $f$ en $g$. Het vlakdeel $W$ ligt onder de grafiek van $g$, tot aan de $x$-as. Bereken exact de waarde van $a$ waarvoor $O(V) = O(W)$.$h15sql$, 3, $h15sql$Deel 3: $4 = \dfrac{5}{3}a$, dus $a = \dfrac{12}{5}$. Die waarde ligt tussen $0$ en $4$.$h15sql$),
  ('h15b_parameter', 'h15b_parameter', $h15sql$Voor elke $p > 1$ sluit de grafiek van $f(x) = \dfrac{1}{x}$ met de $x$-as en de lijnen $x = 1$ en $x = p$ een vlakdeel $V_p$ in. Bereken exact de waarde van $p$ waarvoor de oppervlakte van $V_p$ gelijk is aan $\ln(3)$.$h15sql$, 0, $h15sql$Hier spelen alle drie de delen: het verhaal wordt een integraal, die reken je exact uit, en met die uitkomst vind je de gevraagde waarde.$h15sql$),
  ('h15b_parameter', 'h15b_parameter', $h15sql$Voor elke $p > 1$ sluit de grafiek van $f(x) = \dfrac{1}{x}$ met de $x$-as en de lijnen $x = 1$ en $x = p$ een vlakdeel $V_p$ in. Bereken exact de waarde van $p$ waarvoor de oppervlakte van $V_p$ gelijk is aan $\ln(3)$.$h15sql$, 1, $h15sql$Op $[1, p]$ is $f(x) > 0$. $O(V_p) = \displaystyle\int_{1}^{p} \dfrac{1}{x}\,\mathrm{d}x$.$h15sql$),
  ('h15b_parameter', 'h15b_parameter', $h15sql$Voor elke $p > 1$ sluit de grafiek van $f(x) = \dfrac{1}{x}$ met de $x$-as en de lijnen $x = 1$ en $x = p$ een vlakdeel $V_p$ in. Bereken exact de waarde van $p$ waarvoor de oppervlakte van $V_p$ gelijk is aan $\ln(3)$.$h15sql$, 2, $h15sql$Een primitieve is $\ln(x)$. Dus $O(V_p) = \ln(p) - \ln(1) = \ln(p)$.$h15sql$),
  ('h15b_parameter', 'h15b_parameter', $h15sql$Voor elke $p > 1$ sluit de grafiek van $f(x) = \dfrac{1}{x}$ met de $x$-as en de lijnen $x = 1$ en $x = p$ een vlakdeel $V_p$ in. Bereken exact de waarde van $p$ waarvoor de oppervlakte van $V_p$ gelijk is aan $\ln(3)$.$h15sql$, 3, $h15sql$Deel 3: $\ln(p) = \ln(3)$, dus $p = 3$.$h15sql$),
  ('h15b_parameter', 'h15b_parameter', $h15sql$Voor elke $a > 0$ snijden de grafieken van $f(x) = x$ en $g(x) = ax^{2}$ elkaar in de oorsprong en in $\left(\dfrac{1}{a}, \dfrac{1}{a}\right)$. Het vlakdeel $V_a$ ligt daartussen. Bereken exact de waarde van $a$ waarvoor de oppervlakte van $V_a$ gelijk is aan $\dfrac{1}{24}$.$h15sql$, 0, $h15sql$Hier spelen alle drie de delen: het verhaal wordt een integraal, die reken je exact uit, en met die uitkomst vind je de gevraagde waarde.$h15sql$),
  ('h15b_parameter', 'h15b_parameter', $h15sql$Voor elke $a > 0$ snijden de grafieken van $f(x) = x$ en $g(x) = ax^{2}$ elkaar in de oorsprong en in $\left(\dfrac{1}{a}, \dfrac{1}{a}\right)$. Het vlakdeel $V_a$ ligt daartussen. Bereken exact de waarde van $a$ waarvoor de oppervlakte van $V_a$ gelijk is aan $\dfrac{1}{24}$.$h15sql$, 1, $h15sql$Op $\left(0, \dfrac{1}{a}\right)$ ligt $y = x$ boven $y = ax^{2}$. $O(V_a) = \displaystyle\int_{0}^{1/a} \left(x - ax^{2}\right)\,\mathrm{d}x$.$h15sql$),
  ('h15b_parameter', 'h15b_parameter', $h15sql$Voor elke $a > 0$ snijden de grafieken van $f(x) = x$ en $g(x) = ax^{2}$ elkaar in de oorsprong en in $\left(\dfrac{1}{a}, \dfrac{1}{a}\right)$. Het vlakdeel $V_a$ ligt daartussen. Bereken exact de waarde van $a$ waarvoor de oppervlakte van $V_a$ gelijk is aan $\dfrac{1}{24}$.$h15sql$, 2, $h15sql$Een primitieve is $\dfrac{1}{2}x^{2} - \dfrac{a}{3}x^{3}$. Invullen van de bovengrens geeft $\dfrac{1}{2a^{2}} - \dfrac{1}{3a^{2}} = \dfrac{1}{6a^{2}}$.$h15sql$),
  ('h15b_parameter', 'h15b_parameter', $h15sql$Voor elke $a > 0$ snijden de grafieken van $f(x) = x$ en $g(x) = ax^{2}$ elkaar in de oorsprong en in $\left(\dfrac{1}{a}, \dfrac{1}{a}\right)$. Het vlakdeel $V_a$ ligt daartussen. Bereken exact de waarde van $a$ waarvoor de oppervlakte van $V_a$ gelijk is aan $\dfrac{1}{24}$.$h15sql$, 3, $h15sql$Deel 3: $\dfrac{1}{6a^{2}} = \dfrac{1}{24}$, dus $a^{2} = 4$. Omdat $a > 0$ is $a = 2$.$h15sql$),
  ('h15b_parameter', 'h15b_parameter', $h15sql$Voor elke $p > 0$ sluit de grafiek van $f(x) = e^{x}$ met de $x$-as, de $y$-as en de lijn $x = p$ een vlakdeel $V_p$ in. Bereken exact de waarde van $p$ waarvoor de oppervlakte van $V_p$ gelijk is aan $e^{2} - 1$.$h15sql$, 0, $h15sql$Hier spelen alle drie de delen: het verhaal wordt een integraal, die reken je exact uit, en met die uitkomst vind je de gevraagde waarde.$h15sql$),
  ('h15b_parameter', 'h15b_parameter', $h15sql$Voor elke $p > 0$ sluit de grafiek van $f(x) = e^{x}$ met de $x$-as, de $y$-as en de lijn $x = p$ een vlakdeel $V_p$ in. Bereken exact de waarde van $p$ waarvoor de oppervlakte van $V_p$ gelijk is aan $e^{2} - 1$.$h15sql$, 1, $h15sql$$f(x) > 0$, dus $O(V_p) = \displaystyle\int_{0}^{p} e^{x}\,\mathrm{d}x$.$h15sql$),
  ('h15b_parameter', 'h15b_parameter', $h15sql$Voor elke $p > 0$ sluit de grafiek van $f(x) = e^{x}$ met de $x$-as, de $y$-as en de lijn $x = p$ een vlakdeel $V_p$ in. Bereken exact de waarde van $p$ waarvoor de oppervlakte van $V_p$ gelijk is aan $e^{2} - 1$.$h15sql$, 2, $h15sql$Een primitieve is $e^{x}$. Dus $O(V_p) = e^{p} - 1$.$h15sql$),
  ('h15b_parameter', 'h15b_parameter', $h15sql$Voor elke $p > 0$ sluit de grafiek van $f(x) = e^{x}$ met de $x$-as, de $y$-as en de lijn $x = p$ een vlakdeel $V_p$ in. Bereken exact de waarde van $p$ waarvoor de oppervlakte van $V_p$ gelijk is aan $e^{2} - 1$.$h15sql$, 3, $h15sql$Deel 3: $e^{p} - 1 = e^{2} - 1$, dus $e^{p} = e^{2}$ en $p = 2$.$h15sql$),
  ('h15b_parameter', 'h15b_parameter', $h15sql$Voor elke $p > 0$ sluit de grafiek van $f(x) = p(4 - x^{2})$ met de $x$-as een vlakdeel $V_p$ in. Bereken exact de waarde van $p$ waarvoor de oppervlakte van $V_p$ gelijk is aan $16$.$h15sql$, 0, $h15sql$Hier spelen alle drie de delen: het verhaal wordt een integraal, die reken je exact uit, en met die uitkomst vind je de gevraagde waarde.$h15sql$),
  ('h15b_parameter', 'h15b_parameter', $h15sql$Voor elke $p > 0$ sluit de grafiek van $f(x) = p(4 - x^{2})$ met de $x$-as een vlakdeel $V_p$ in. Bereken exact de waarde van $p$ waarvoor de oppervlakte van $V_p$ gelijk is aan $16$.$h15sql$, 1, $h15sql$De grafiek snijdt de $x$-as in $x = -2$ en $x = 2$. Voor $p > 0$ ligt hij daartussen boven de as. $O(V_p) = \displaystyle\int_{-2}^{2} p(4 - x^{2})\,\mathrm{d}x$.$h15sql$),
  ('h15b_parameter', 'h15b_parameter', $h15sql$Voor elke $p > 0$ sluit de grafiek van $f(x) = p(4 - x^{2})$ met de $x$-as een vlakdeel $V_p$ in. Bereken exact de waarde van $p$ waarvoor de oppervlakte van $V_p$ gelijk is aan $16$.$h15sql$, 2, $h15sql$Zonder de $p$ is een primitieve $4x - \dfrac{1}{3}x^{3}$. Van $-2$ tot $2$ geeft dat $\dfrac{32}{3}$. Dus $O(V_p) = \dfrac{32}{3}p$.$h15sql$),
  ('h15b_parameter', 'h15b_parameter', $h15sql$Voor elke $p > 0$ sluit de grafiek van $f(x) = p(4 - x^{2})$ met de $x$-as een vlakdeel $V_p$ in. Bereken exact de waarde van $p$ waarvoor de oppervlakte van $V_p$ gelijk is aan $16$.$h15sql$, 3, $h15sql$Deel 3: $\dfrac{32}{3}p = 16$, dus $p = 16 \cdot \dfrac{3}{32} = \dfrac{3}{2}$.$h15sql$),
  ('h15c_xas', 'h15c_xas', $h15sql$Het vlakdeel $V$ wordt ingesloten door de grafiek van $f(x) = x$, de $x$-as en de lijn $x = 3$. Het lichaam $L$ ontstaat als $V$ wentelt om de $x$-as. Bereken exact de inhoud van $L$.$h15sql$, 0, $h15sql$Hier spelen deel 1 en deel 2 van de driedeling: eerst het verhaal vertalen naar een integraal, dan die integraal exact uitrekenen. De inhoud bij wentelen om de $x$-as is $\pi$ keer de integraal van het kwadraat van $f$.$h15sql$),
  ('h15c_xas', 'h15c_xas', $h15sql$Het vlakdeel $V$ wordt ingesloten door de grafiek van $f(x) = x$, de $x$-as en de lijn $x = 3$. Het lichaam $L$ ontstaat als $V$ wentelt om de $x$-as. Bereken exact de inhoud van $L$.$h15sql$, 1, $h15sql$$I(L) = \pi \displaystyle\int_{0}^{3} x^{2}\,\mathrm{d}x$.$h15sql$),
  ('h15c_xas', 'h15c_xas', $h15sql$Het vlakdeel $V$ wordt ingesloten door de grafiek van $f(x) = x$, de $x$-as en de lijn $x = 3$. Het lichaam $L$ ontstaat als $V$ wentelt om de $x$-as. Bereken exact de inhoud van $L$.$h15sql$, 2, $h15sql$Een primitieve van de integrand is $F(x) = \pi \cdot \dfrac{1}{3}x^{3}$.$h15sql$),
  ('h15c_xas', 'h15c_xas', $h15sql$Het vlakdeel $V$ wordt ingesloten door de grafiek van $f(x) = x$, de $x$-as en de lijn $x = 3$. Het lichaam $L$ ontstaat als $V$ wentelt om de $x$-as. Bereken exact de inhoud van $L$.$h15sql$, 3, $h15sql$$F(3) - F(0) = \pi \cdot 9 = 9\pi$. De inhoud is $9\pi$.$h15sql$),
  ('h15c_xas', 'h15c_xas', $h15sql$Het vlakdeel $V$ wordt ingesloten door de lijn $y = 2$, de $x$-as en de lijnen $x = 0$ en $x = 3$. Het lichaam $L$ ontstaat als $V$ wentelt om de $x$-as. Bereken exact de inhoud van $L$.$h15sql$, 0, $h15sql$Hier spelen deel 1 en deel 2 van de driedeling: eerst het verhaal vertalen naar een integraal, dan die integraal exact uitrekenen. De straal van de schijf is overal $2$.$h15sql$),
  ('h15c_xas', 'h15c_xas', $h15sql$Het vlakdeel $V$ wordt ingesloten door de lijn $y = 2$, de $x$-as en de lijnen $x = 0$ en $x = 3$. Het lichaam $L$ ontstaat als $V$ wentelt om de $x$-as. Bereken exact de inhoud van $L$.$h15sql$, 1, $h15sql$$I(L) = \pi \displaystyle\int_{0}^{3} 2^{2}\,\mathrm{d}x = \pi \displaystyle\int_{0}^{3} 4\,\mathrm{d}x$.$h15sql$),
  ('h15c_xas', 'h15c_xas', $h15sql$Het vlakdeel $V$ wordt ingesloten door de lijn $y = 2$, de $x$-as en de lijnen $x = 0$ en $x = 3$. Het lichaam $L$ ontstaat als $V$ wentelt om de $x$-as. Bereken exact de inhoud van $L$.$h15sql$, 2, $h15sql$Een primitieve van de integrand is $F(x) = 4\pi x$.$h15sql$),
  ('h15c_xas', 'h15c_xas', $h15sql$Het vlakdeel $V$ wordt ingesloten door de lijn $y = 2$, de $x$-as en de lijnen $x = 0$ en $x = 3$. Het lichaam $L$ ontstaat als $V$ wentelt om de $x$-as. Bereken exact de inhoud van $L$.$h15sql$, 3, $h15sql$$F(3) - F(0) = 12\pi$. De inhoud is $12\pi$.$h15sql$),
  ('h15c_xas', 'h15c_xas', $h15sql$Het vlakdeel $V$ wordt ingesloten door de grafiek van $f(x) = \sqrt{x}$, de $x$-as en de lijn $x = 4$. Het lichaam $L$ ontstaat als $V$ wentelt om de $x$-as. Bereken exact de inhoud van $L$.$h15sql$, 0, $h15sql$Hier spelen deel 1 en deel 2 van de driedeling: eerst het verhaal vertalen naar een integraal, dan die integraal exact uitrekenen. Het kwadraat van $\sqrt{x}$ is gewoon $x$.$h15sql$),
  ('h15c_xas', 'h15c_xas', $h15sql$Het vlakdeel $V$ wordt ingesloten door de grafiek van $f(x) = \sqrt{x}$, de $x$-as en de lijn $x = 4$. Het lichaam $L$ ontstaat als $V$ wentelt om de $x$-as. Bereken exact de inhoud van $L$.$h15sql$, 1, $h15sql$$I(L) = \pi \displaystyle\int_{0}^{4} \left(\sqrt{x}\right)^{2}\,\mathrm{d}x = \pi \displaystyle\int_{0}^{4} x\,\mathrm{d}x$.$h15sql$),
  ('h15c_xas', 'h15c_xas', $h15sql$Het vlakdeel $V$ wordt ingesloten door de grafiek van $f(x) = \sqrt{x}$, de $x$-as en de lijn $x = 4$. Het lichaam $L$ ontstaat als $V$ wentelt om de $x$-as. Bereken exact de inhoud van $L$.$h15sql$, 2, $h15sql$Een primitieve van de integrand is $F(x) = \pi \cdot \dfrac{1}{2}x^{2}$.$h15sql$),
  ('h15c_xas', 'h15c_xas', $h15sql$Het vlakdeel $V$ wordt ingesloten door de grafiek van $f(x) = \sqrt{x}$, de $x$-as en de lijn $x = 4$. Het lichaam $L$ ontstaat als $V$ wentelt om de $x$-as. Bereken exact de inhoud van $L$.$h15sql$, 3, $h15sql$$F(4) - F(0) = \pi \cdot 8 = 8\pi$. De inhoud is $8\pi$.$h15sql$),
  ('h15c_xas', 'h15c_xas', $h15sql$Het vlakdeel $V$ wordt ingesloten door de grafiek van $f(x) = x + 1$, de $x$-as en de lijnen $x = 0$ en $x = 1$. Het lichaam $L$ ontstaat als $V$ wentelt om de $x$-as. Bereken exact de inhoud van $L$.$h15sql$, 0, $h15sql$Hier spelen deel 1 en deel 2 van de driedeling: eerst het verhaal vertalen naar een integraal, dan die integraal exact uitrekenen. De straal is $x + 1$. Kwadrateer die eerst.$h15sql$),
  ('h15c_xas', 'h15c_xas', $h15sql$Het vlakdeel $V$ wordt ingesloten door de grafiek van $f(x) = x + 1$, de $x$-as en de lijnen $x = 0$ en $x = 1$. Het lichaam $L$ ontstaat als $V$ wentelt om de $x$-as. Bereken exact de inhoud van $L$.$h15sql$, 1, $h15sql$$I(L) = \pi \displaystyle\int_{0}^{1} (x + 1)^{2}\,\mathrm{d}x = \pi \displaystyle\int_{0}^{1} (x^{2} + 2x + 1)\,\mathrm{d}x$.$h15sql$),
  ('h15c_xas', 'h15c_xas', $h15sql$Het vlakdeel $V$ wordt ingesloten door de grafiek van $f(x) = x + 1$, de $x$-as en de lijnen $x = 0$ en $x = 1$. Het lichaam $L$ ontstaat als $V$ wentelt om de $x$-as. Bereken exact de inhoud van $L$.$h15sql$, 2, $h15sql$Een primitieve van de integrand is $F(x) = \pi\left(\dfrac{1}{3}x^{3} + x^{2} + x\right)$.$h15sql$),
  ('h15c_xas', 'h15c_xas', $h15sql$Het vlakdeel $V$ wordt ingesloten door de grafiek van $f(x) = x + 1$, de $x$-as en de lijnen $x = 0$ en $x = 1$. Het lichaam $L$ ontstaat als $V$ wentelt om de $x$-as. Bereken exact de inhoud van $L$.$h15sql$, 3, $h15sql$$F(1) - F(0) = \pi\left(\dfrac{1}{3} + 1 + 1\right) = \dfrac{7}{3}\pi$. De inhoud is $\dfrac{7}{3}\pi$.$h15sql$),
  ('h15c_xas', 'h15c_xas', $h15sql$Het vlakdeel $V$ wordt ingesloten door de lijn $y = 3 - x$, de $x$-as en de $y$-as. Het lichaam $L$ ontstaat als $V$ wentelt om de $x$-as. Bereken exact de inhoud van $L$.$h15sql$, 0, $h15sql$Hier spelen deel 1 en deel 2 van de driedeling: eerst het verhaal vertalen naar een integraal, dan die integraal exact uitrekenen. De lijn snijdt de $x$-as in $x = 3$ en de $y$-as in $y = 3$. Op $[0, 3]$ ligt hij boven de $x$-as.$h15sql$),
  ('h15c_xas', 'h15c_xas', $h15sql$Het vlakdeel $V$ wordt ingesloten door de lijn $y = 3 - x$, de $x$-as en de $y$-as. Het lichaam $L$ ontstaat als $V$ wentelt om de $x$-as. Bereken exact de inhoud van $L$.$h15sql$, 1, $h15sql$$I(L) = \pi \displaystyle\int_{0}^{3} (3 - x)^{2}\,\mathrm{d}x = \pi \displaystyle\int_{0}^{3} (9 - 6x + x^{2})\,\mathrm{d}x$.$h15sql$),
  ('h15c_xas', 'h15c_xas', $h15sql$Het vlakdeel $V$ wordt ingesloten door de lijn $y = 3 - x$, de $x$-as en de $y$-as. Het lichaam $L$ ontstaat als $V$ wentelt om de $x$-as. Bereken exact de inhoud van $L$.$h15sql$, 2, $h15sql$Een primitieve van de integrand is $F(x) = \pi\left(9x - 3x^{2} + \dfrac{1}{3}x^{3}\right)$.$h15sql$),
  ('h15c_xas', 'h15c_xas', $h15sql$Het vlakdeel $V$ wordt ingesloten door de lijn $y = 3 - x$, de $x$-as en de $y$-as. Het lichaam $L$ ontstaat als $V$ wentelt om de $x$-as. Bereken exact de inhoud van $L$.$h15sql$, 3, $h15sql$$F(3) - F(0) = \pi(27 - 27 + 9) = 9\pi$. De inhoud is $9\pi$.$h15sql$),
  ('h15c_xas', 'h15c_xas', $h15sql$Het vlakdeel $V$ wordt ingesloten door de grafieken van $f(x) = x$ en $g(x) = x^{2}$. Het lichaam $L$ ontstaat als $V$ wentelt om de $x$-as. Bereken exact de inhoud van $L$.$h15sql$, 0, $h15sql$Hier spelen deel 1 en deel 2 van de driedeling: eerst het verhaal vertalen naar een integraal, dan die integraal exact uitrekenen. De grafieken snijden elkaar in $x = 0$ en $x = 1$. Op dat stuk ligt $y = x$ boven $y = x^{2}$. De inhoud is $\pi$ keer de integraal van het verschil van de kwadraten.$h15sql$),
  ('h15c_xas', 'h15c_xas', $h15sql$Het vlakdeel $V$ wordt ingesloten door de grafieken van $f(x) = x$ en $g(x) = x^{2}$. Het lichaam $L$ ontstaat als $V$ wentelt om de $x$-as. Bereken exact de inhoud van $L$.$h15sql$, 1, $h15sql$$I(L) = \pi \displaystyle\int_{0}^{1} \left(x^{2} - (x^{2})^{2}\right)\,\mathrm{d}x = \pi \displaystyle\int_{0}^{1} (x^{2} - x^{4})\,\mathrm{d}x$.$h15sql$),
  ('h15c_xas', 'h15c_xas', $h15sql$Het vlakdeel $V$ wordt ingesloten door de grafieken van $f(x) = x$ en $g(x) = x^{2}$. Het lichaam $L$ ontstaat als $V$ wentelt om de $x$-as. Bereken exact de inhoud van $L$.$h15sql$, 2, $h15sql$Een primitieve van de integrand is $F(x) = \pi\left(\dfrac{1}{3}x^{3} - \dfrac{1}{5}x^{5}\right)$.$h15sql$),
  ('h15c_xas', 'h15c_xas', $h15sql$Het vlakdeel $V$ wordt ingesloten door de grafieken van $f(x) = x$ en $g(x) = x^{2}$. Het lichaam $L$ ontstaat als $V$ wentelt om de $x$-as. Bereken exact de inhoud van $L$.$h15sql$, 3, $h15sql$$F(1) - F(0) = \pi\left(\dfrac{1}{3} - \dfrac{1}{5}\right) = \dfrac{2}{15}\pi$. De inhoud is $\dfrac{2}{15}\pi$.$h15sql$),
  ('h15c_xas', 'h15c_xas', $h15sql$Het vlakdeel $V$ wordt ingesloten door de lijnen $y = 2$ en $y = x$ en de $y$-as. Het lichaam $L$ ontstaat als $V$ wentelt om de $x$-as. Bereken exact de inhoud van $L$.$h15sql$, 0, $h15sql$Hier spelen deel 1 en deel 2 van de driedeling: eerst het verhaal vertalen naar een integraal, dan die integraal exact uitrekenen. De lijnen snijden elkaar in $x = 2$. Op $[0, 2]$ is de buitenste straal $2$ en de binnenste straal $x$.$h15sql$),
  ('h15c_xas', 'h15c_xas', $h15sql$Het vlakdeel $V$ wordt ingesloten door de lijnen $y = 2$ en $y = x$ en de $y$-as. Het lichaam $L$ ontstaat als $V$ wentelt om de $x$-as. Bereken exact de inhoud van $L$.$h15sql$, 1, $h15sql$$I(L) = \pi \displaystyle\int_{0}^{2} \left(2^{2} - x^{2}\right)\,\mathrm{d}x = \pi \displaystyle\int_{0}^{2} (4 - x^{2})\,\mathrm{d}x$.$h15sql$),
  ('h15c_xas', 'h15c_xas', $h15sql$Het vlakdeel $V$ wordt ingesloten door de lijnen $y = 2$ en $y = x$ en de $y$-as. Het lichaam $L$ ontstaat als $V$ wentelt om de $x$-as. Bereken exact de inhoud van $L$.$h15sql$, 2, $h15sql$Een primitieve van de integrand is $F(x) = \pi\left(4x - \dfrac{1}{3}x^{3}\right)$.$h15sql$),
  ('h15c_xas', 'h15c_xas', $h15sql$Het vlakdeel $V$ wordt ingesloten door de lijnen $y = 2$ en $y = x$ en de $y$-as. Het lichaam $L$ ontstaat als $V$ wentelt om de $x$-as. Bereken exact de inhoud van $L$.$h15sql$, 3, $h15sql$$F(2) - F(0) = \pi\left(8 - \dfrac{8}{3}\right) = \dfrac{16}{3}\pi$. De inhoud is $\dfrac{16}{3}\pi$.$h15sql$),
  ('h15c_xas', 'h15c_xas', $h15sql$Het vlakdeel $V$ wordt ingesloten door de grafiek van $f(x) = 2x$, de $x$-as en de lijn $x = 2$. Het lichaam $L$ ontstaat als $V$ wentelt om de $x$-as. Bereken exact de inhoud van $L$.$h15sql$, 0, $h15sql$Hier spelen deel 1 en deel 2 van de driedeling: eerst het verhaal vertalen naar een integraal, dan die integraal exact uitrekenen. De straal is $2x$, dus het kwadraat is $4x^{2}$.$h15sql$),
  ('h15c_xas', 'h15c_xas', $h15sql$Het vlakdeel $V$ wordt ingesloten door de grafiek van $f(x) = 2x$, de $x$-as en de lijn $x = 2$. Het lichaam $L$ ontstaat als $V$ wentelt om de $x$-as. Bereken exact de inhoud van $L$.$h15sql$, 1, $h15sql$$I(L) = \pi \displaystyle\int_{0}^{2} (2x)^{2}\,\mathrm{d}x = \pi \displaystyle\int_{0}^{2} 4x^{2}\,\mathrm{d}x$.$h15sql$),
  ('h15c_xas', 'h15c_xas', $h15sql$Het vlakdeel $V$ wordt ingesloten door de grafiek van $f(x) = 2x$, de $x$-as en de lijn $x = 2$. Het lichaam $L$ ontstaat als $V$ wentelt om de $x$-as. Bereken exact de inhoud van $L$.$h15sql$, 2, $h15sql$Een primitieve van de integrand is $F(x) = \pi \cdot \dfrac{4}{3}x^{3}$.$h15sql$),
  ('h15c_xas', 'h15c_xas', $h15sql$Het vlakdeel $V$ wordt ingesloten door de grafiek van $f(x) = 2x$, de $x$-as en de lijn $x = 2$. Het lichaam $L$ ontstaat als $V$ wentelt om de $x$-as. Bereken exact de inhoud van $L$.$h15sql$, 3, $h15sql$$F(2) - F(0) = \pi \cdot \dfrac{4}{3} \cdot 8 = \dfrac{32}{3}\pi$. De inhoud is $\dfrac{32}{3}\pi$.$h15sql$),
  ('h15c_yas', 'h15c_yas', $h15sql$Het vlakdeel $V$ wordt ingesloten door de lijn $y = x$, de $y$-as en de lijn $y = 2$. Het lichaam $L$ ontstaat als $V$ wentelt om de $y$-as. Bereken exact de inhoud van $L$.$h15sql$, 0, $h15sql$Hier spelen deel 1 en deel 2 van de driedeling: eerst het verhaal vertalen naar een integraal, dan die integraal exact uitrekenen. Bij wentelen om de $y$-as is de straal de $x$-waarde, en integreer je naar $y$.$h15sql$),
  ('h15c_yas', 'h15c_yas', $h15sql$Het vlakdeel $V$ wordt ingesloten door de lijn $y = x$, de $y$-as en de lijn $y = 2$. Het lichaam $L$ ontstaat als $V$ wentelt om de $y$-as. Bereken exact de inhoud van $L$.$h15sql$, 1, $h15sql$Uit $y = x$ volgt $x = y$. Met $y$ van $0$ tot $2$: $I(L) = \pi \displaystyle\int_{0}^{2} y^{2}\,\mathrm{d}y$. In de berekening hieronder heet de integratievariabele $x$.$h15sql$),
  ('h15c_yas', 'h15c_yas', $h15sql$Het vlakdeel $V$ wordt ingesloten door de lijn $y = x$, de $y$-as en de lijn $y = 2$. Het lichaam $L$ ontstaat als $V$ wentelt om de $y$-as. Bereken exact de inhoud van $L$.$h15sql$, 2, $h15sql$Een primitieve van $\pi x^{2}$ is $F(x) = \pi \cdot \dfrac{1}{3}x^{3}$.$h15sql$),
  ('h15c_yas', 'h15c_yas', $h15sql$Het vlakdeel $V$ wordt ingesloten door de lijn $y = x$, de $y$-as en de lijn $y = 2$. Het lichaam $L$ ontstaat als $V$ wentelt om de $y$-as. Bereken exact de inhoud van $L$.$h15sql$, 3, $h15sql$$F(2) - F(0) = \dfrac{8}{3}\pi$. De inhoud is $\dfrac{8}{3}\pi$.$h15sql$),
  ('h15c_yas', 'h15c_yas', $h15sql$Het vlakdeel $V$ wordt ingesloten door de grafiek van $y = \sqrt{x}$, de $x$-as en de lijn $x = 4$. Het lichaam $L$ ontstaat als $V$ wentelt om de $y$-as. Bereken exact de inhoud van $L$.$h15sql$, 0, $h15sql$Hier spelen deel 1 en deel 2 van de driedeling: eerst het verhaal vertalen naar een integraal, dan die integraal exact uitrekenen. Schrijf $x$ als functie van $y$ en integreer het kwadraat van die straal.$h15sql$),
  ('h15c_yas', 'h15c_yas', $h15sql$Het vlakdeel $V$ wordt ingesloten door de grafiek van $y = \sqrt{x}$, de $x$-as en de lijn $x = 4$. Het lichaam $L$ ontstaat als $V$ wentelt om de $y$-as. Bereken exact de inhoud van $L$.$h15sql$, 1, $h15sql$$y = \sqrt{x}$ geeft $x = y^{2}$, en $y$ loopt van $0$ tot $2$. $I(L) = \pi \displaystyle\int_{0}^{2} (y^{2})^{2}\,\mathrm{d}y = \pi \displaystyle\int_{0}^{2} y^{4}\,\mathrm{d}y$.$h15sql$),
  ('h15c_yas', 'h15c_yas', $h15sql$Het vlakdeel $V$ wordt ingesloten door de grafiek van $y = \sqrt{x}$, de $x$-as en de lijn $x = 4$. Het lichaam $L$ ontstaat als $V$ wentelt om de $y$-as. Bereken exact de inhoud van $L$.$h15sql$, 2, $h15sql$Een primitieve van $\pi x^{4}$ is $F(x) = \pi \cdot \dfrac{1}{5}x^{5}$.$h15sql$),
  ('h15c_yas', 'h15c_yas', $h15sql$Het vlakdeel $V$ wordt ingesloten door de grafiek van $y = \sqrt{x}$, de $x$-as en de lijn $x = 4$. Het lichaam $L$ ontstaat als $V$ wentelt om de $y$-as. Bereken exact de inhoud van $L$.$h15sql$, 3, $h15sql$$F(2) - F(0) = \pi \cdot \dfrac{32}{5} = \dfrac{32}{5}\pi$. De inhoud is $\dfrac{32}{5}\pi$.$h15sql$),
  ('h15c_yas', 'h15c_yas', $h15sql$Het vlakdeel $V$ wordt ingesloten door de grafiek van $y = x^{2}$, de $x$-as en de lijn $x = 2$. Het lichaam $L$ ontstaat als $V$ wentelt om de $y$-as. Bereken exact de inhoud van $L$.$h15sql$, 0, $h15sql$Hier spelen deel 1 en deel 2 van de driedeling: eerst het verhaal vertalen naar een integraal, dan die integraal exact uitrekenen. Druk de straal uit in $y$.$h15sql$),
  ('h15c_yas', 'h15c_yas', $h15sql$Het vlakdeel $V$ wordt ingesloten door de grafiek van $y = x^{2}$, de $x$-as en de lijn $x = 2$. Het lichaam $L$ ontstaat als $V$ wentelt om de $y$-as. Bereken exact de inhoud van $L$.$h15sql$, 1, $h15sql$$y = x^{2}$ met $x \ge 0$ geeft $x = \sqrt{y}$. En $y$ loopt van $0$ tot $4$. $I(L) = \pi \displaystyle\int_{0}^{4} y\,\mathrm{d}y$.$h15sql$),
  ('h15c_yas', 'h15c_yas', $h15sql$Het vlakdeel $V$ wordt ingesloten door de grafiek van $y = x^{2}$, de $x$-as en de lijn $x = 2$. Het lichaam $L$ ontstaat als $V$ wentelt om de $y$-as. Bereken exact de inhoud van $L$.$h15sql$, 2, $h15sql$Een primitieve van $\pi x$ is $F(x) = \pi \cdot \dfrac{1}{2}x^{2}$.$h15sql$),
  ('h15c_yas', 'h15c_yas', $h15sql$Het vlakdeel $V$ wordt ingesloten door de grafiek van $y = x^{2}$, de $x$-as en de lijn $x = 2$. Het lichaam $L$ ontstaat als $V$ wentelt om de $y$-as. Bereken exact de inhoud van $L$.$h15sql$, 3, $h15sql$$F(4) - F(0) = 8\pi$. De inhoud is $8\pi$.$h15sql$),
  ('h15c_yas', 'h15c_yas', $h15sql$Het vlakdeel $V$ wordt ingesloten door de lijn $y = 2x$, de $y$-as en de lijn $y = 4$. Het lichaam $L$ ontstaat als $V$ wentelt om de $y$-as. Bereken exact de inhoud van $L$.$h15sql$, 0, $h15sql$Hier spelen deel 1 en deel 2 van de driedeling: eerst het verhaal vertalen naar een integraal, dan die integraal exact uitrekenen. Uit $y = 2x$ volgt de straal $x = dfrac{1}{2}y$.$h15sql$),
  ('h15c_yas', 'h15c_yas', $h15sql$Het vlakdeel $V$ wordt ingesloten door de lijn $y = 2x$, de $y$-as en de lijn $y = 4$. Het lichaam $L$ ontstaat als $V$ wentelt om de $y$-as. Bereken exact de inhoud van $L$.$h15sql$, 1, $h15sql$$y$ loopt van $0$ tot $4$. $I(L) = \pi \displaystyle\int_{0}^{4} \left(\dfrac{y}{2}\right)^{2}\,\mathrm{d}y = \pi \displaystyle\int_{0}^{4} \dfrac{1}{4}y^{2}\,\mathrm{d}y$.$h15sql$),
  ('h15c_yas', 'h15c_yas', $h15sql$Het vlakdeel $V$ wordt ingesloten door de lijn $y = 2x$, de $y$-as en de lijn $y = 4$. Het lichaam $L$ ontstaat als $V$ wentelt om de $y$-as. Bereken exact de inhoud van $L$.$h15sql$, 2, $h15sql$Een primitieve van $\pi\left(\dfrac{x}{2}\right)^{2}$ is $F(x) = \pi \cdot \dfrac{1}{12}x^{3}$.$h15sql$),
  ('h15c_yas', 'h15c_yas', $h15sql$Het vlakdeel $V$ wordt ingesloten door de lijn $y = 2x$, de $y$-as en de lijn $y = 4$. Het lichaam $L$ ontstaat als $V$ wentelt om de $y$-as. Bereken exact de inhoud van $L$.$h15sql$, 3, $h15sql$$F(4) - F(0) = \pi \cdot \dfrac{64}{12} = \dfrac{16}{3}\pi$. De inhoud is $\dfrac{16}{3}\pi$.$h15sql$),
  ('h15c_yas', 'h15c_yas', $h15sql$Het vlakdeel $V$ wordt ingesloten door de lijnen $y = x$ en $y = 2x$ en de lijn $y = 2$. Het lichaam $L$ ontstaat als $V$ wentelt om de $y$-as. Bereken exact de inhoud van $L$.$h15sql$, 0, $h15sql$Hier spelen deel 1 en deel 2 van de driedeling: eerst het verhaal vertalen naar een integraal, dan die integraal exact uitrekenen. Op een hoogte $y$ loopt het vlakdeel van de lijn $y = 2x$ tot de lijn $y = x$. De buitenste straal is $y$, de binnenste is $\dfrac{1}{2}y$.$h15sql$),
  ('h15c_yas', 'h15c_yas', $h15sql$Het vlakdeel $V$ wordt ingesloten door de lijnen $y = x$ en $y = 2x$ en de lijn $y = 2$. Het lichaam $L$ ontstaat als $V$ wentelt om de $y$-as. Bereken exact de inhoud van $L$.$h15sql$, 1, $h15sql$$I(L) = \pi \displaystyle\int_{0}^{2} \left(y^{2} - \left(\dfrac{y}{2}\right)^{2}\right)\,\mathrm{d}y = \pi \displaystyle\int_{0}^{2} \dfrac{3}{4}y^{2}\,\mathrm{d}y$.$h15sql$),
  ('h15c_yas', 'h15c_yas', $h15sql$Het vlakdeel $V$ wordt ingesloten door de lijnen $y = x$ en $y = 2x$ en de lijn $y = 2$. Het lichaam $L$ ontstaat als $V$ wentelt om de $y$-as. Bereken exact de inhoud van $L$.$h15sql$, 2, $h15sql$Een primitieve van $\pi\left(x^{2} - \left(\dfrac{x}{2}\right)^{2}\right)$ is $F(x) = \pi \cdot \dfrac{1}{4}x^{3}$.$h15sql$),
  ('h15c_yas', 'h15c_yas', $h15sql$Het vlakdeel $V$ wordt ingesloten door de lijnen $y = x$ en $y = 2x$ en de lijn $y = 2$. Het lichaam $L$ ontstaat als $V$ wentelt om de $y$-as. Bereken exact de inhoud van $L$.$h15sql$, 3, $h15sql$$F(2) - F(0) = \pi \cdot 2 = 2\pi$. De inhoud is $2\pi$.$h15sql$),
  ('h15c_yas', 'h15c_yas', $h15sql$Het vlakdeel $V$ is de rechthoek met hoekpunten $(0, 0)$, $(3, 0)$, $(3, 2)$ en $(0, 2)$. Het lichaam $L$ ontstaat als $V$ wentelt om de $y$-as. Bereken exact de inhoud van $L$.$h15sql$, 0, $h15sql$Hier spelen deel 1 en deel 2 van de driedeling: eerst het verhaal vertalen naar een integraal, dan die integraal exact uitrekenen. De straal is overal $3$, en de hoogte loopt van $y = 0$ tot $y = 2$.$h15sql$),
  ('h15c_yas', 'h15c_yas', $h15sql$Het vlakdeel $V$ is de rechthoek met hoekpunten $(0, 0)$, $(3, 0)$, $(3, 2)$ en $(0, 2)$. Het lichaam $L$ ontstaat als $V$ wentelt om de $y$-as. Bereken exact de inhoud van $L$.$h15sql$, 1, $h15sql$$I(L) = \pi \displaystyle\int_{0}^{2} 3^{2}\,\mathrm{d}y = \pi \displaystyle\int_{0}^{2} 9\,\mathrm{d}y$.$h15sql$),
  ('h15c_yas', 'h15c_yas', $h15sql$Het vlakdeel $V$ is de rechthoek met hoekpunten $(0, 0)$, $(3, 0)$, $(3, 2)$ en $(0, 2)$. Het lichaam $L$ ontstaat als $V$ wentelt om de $y$-as. Bereken exact de inhoud van $L$.$h15sql$, 2, $h15sql$Een primitieve van $9\pi$ is $F(x) = 9\pi x$.$h15sql$),
  ('h15c_yas', 'h15c_yas', $h15sql$Het vlakdeel $V$ is de rechthoek met hoekpunten $(0, 0)$, $(3, 0)$, $(3, 2)$ en $(0, 2)$. Het lichaam $L$ ontstaat als $V$ wentelt om de $y$-as. Bereken exact de inhoud van $L$.$h15sql$, 3, $h15sql$$F(2) - F(0) = 18\pi$. De inhoud is $18\pi$.$h15sql$),
  ('h15c_yas', 'h15c_yas', $h15sql$Het vlakdeel $V$ wordt ingesloten door de grafiek van $y = 4 - x^{2}$ en de coördinaatassen in het eerste kwadrant. Het lichaam $L$ ontstaat als $V$ wentelt om de $y$-as. Bereken exact de inhoud van $L$.$h15sql$, 0, $h15sql$Hier spelen deel 1 en deel 2 van de driedeling: eerst het verhaal vertalen naar een integraal, dan die integraal exact uitrekenen. In het eerste kwadrant loopt $y$ van $0$ tot $4$. De straal is de bijbehorende $x$.$h15sql$),
  ('h15c_yas', 'h15c_yas', $h15sql$Het vlakdeel $V$ wordt ingesloten door de grafiek van $y = 4 - x^{2}$ en de coördinaatassen in het eerste kwadrant. Het lichaam $L$ ontstaat als $V$ wentelt om de $y$-as. Bereken exact de inhoud van $L$.$h15sql$, 1, $h15sql$Uit $y = 4 - x^{2}$ volgt $x^{2} = 4 - y$, met $x \ge 0$. $I(L) = \pi \displaystyle\int_{0}^{4} (4 - y)\,\mathrm{d}y$.$h15sql$),
  ('h15c_yas', 'h15c_yas', $h15sql$Het vlakdeel $V$ wordt ingesloten door de grafiek van $y = 4 - x^{2}$ en de coördinaatassen in het eerste kwadrant. Het lichaam $L$ ontstaat als $V$ wentelt om de $y$-as. Bereken exact de inhoud van $L$.$h15sql$, 2, $h15sql$Een primitieve van $\pi(4 - x)$ is $F(x) = \pi\left(4x - \dfrac{1}{2}x^{2}\right)$.$h15sql$),
  ('h15c_yas', 'h15c_yas', $h15sql$Het vlakdeel $V$ wordt ingesloten door de grafiek van $y = 4 - x^{2}$ en de coördinaatassen in het eerste kwadrant. Het lichaam $L$ ontstaat als $V$ wentelt om de $y$-as. Bereken exact de inhoud van $L$.$h15sql$, 3, $h15sql$$F(4) - F(0) = \pi(16 - 8) = 8\pi$. De inhoud is $8\pi$.$h15sql$),
  ('h15c_yas', 'h15c_yas', $h15sql$Het vlakdeel $V$ wordt ingesloten door de grafieken van $x = y$ en $x = y^{2}$, met $0 \le y \le 1$. Het lichaam $L$ ontstaat als $V$ wentelt om de $y$-as. Bereken exact de inhoud van $L$.$h15sql$, 0, $h15sql$Hier spelen deel 1 en deel 2 van de driedeling: eerst het verhaal vertalen naar een integraal, dan die integraal exact uitrekenen. Op $[0, 1]$ is $y ge y^{2}$, dus de buitenste straal is $y$ en de binnenste is $y^{2}$.$h15sql$),
  ('h15c_yas', 'h15c_yas', $h15sql$Het vlakdeel $V$ wordt ingesloten door de grafieken van $x = y$ en $x = y^{2}$, met $0 \le y \le 1$. Het lichaam $L$ ontstaat als $V$ wentelt om de $y$-as. Bereken exact de inhoud van $L$.$h15sql$, 1, $h15sql$$I(L) = \pi \displaystyle\int_{0}^{1} \left(y^{2} - (y^{2})^{2}\right)\,\mathrm{d}y = \pi \displaystyle\int_{0}^{1} (y^{2} - y^{4})\,\mathrm{d}y$.$h15sql$),
  ('h15c_yas', 'h15c_yas', $h15sql$Het vlakdeel $V$ wordt ingesloten door de grafieken van $x = y$ en $x = y^{2}$, met $0 \le y \le 1$. Het lichaam $L$ ontstaat als $V$ wentelt om de $y$-as. Bereken exact de inhoud van $L$.$h15sql$, 2, $h15sql$Een primitieve van $\pi(x^{2} - x^{4})$ is $F(x) = \pi\left(\dfrac{1}{3}x^{3} - \dfrac{1}{5}x^{5}\right)$.$h15sql$),
  ('h15c_yas', 'h15c_yas', $h15sql$Het vlakdeel $V$ wordt ingesloten door de grafieken van $x = y$ en $x = y^{2}$, met $0 \le y \le 1$. Het lichaam $L$ ontstaat als $V$ wentelt om de $y$-as. Bereken exact de inhoud van $L$.$h15sql$, 3, $h15sql$$F(1) - F(0) = \pi\left(\dfrac{1}{3} - \dfrac{1}{5}\right) = \dfrac{2}{15}\pi$. De inhoud is $\dfrac{2}{15}\pi$.$h15sql$),
  ('h15c_vergelijk', 'h15c_vergelijk', $h15sql$Voor elke $p > 0$ ontstaat het lichaam $L_p$ als het vlakdeel onder $y = x$ van $x = 0$ tot $x = p$ wentelt om de $x$-as. Bereken exact de waarde van $p$ waarvoor de inhoud van $L_p$ gelijk is aan $9\pi$.$h15sql$, 0, $h15sql$Hier spelen alle drie de delen: het verhaal wordt een integraal, die reken je exact uit, en met die uitkomst vind je de gevraagde waarde.$h15sql$),
  ('h15c_vergelijk', 'h15c_vergelijk', $h15sql$Voor elke $p > 0$ ontstaat het lichaam $L_p$ als het vlakdeel onder $y = x$ van $x = 0$ tot $x = p$ wentelt om de $x$-as. Bereken exact de waarde van $p$ waarvoor de inhoud van $L_p$ gelijk is aan $9\pi$.$h15sql$, 1, $h15sql$$I(L_p) = \pi \displaystyle\int_{0}^{p} x^{2}\,\mathrm{d}x$.$h15sql$),
  ('h15c_vergelijk', 'h15c_vergelijk', $h15sql$Voor elke $p > 0$ ontstaat het lichaam $L_p$ als het vlakdeel onder $y = x$ van $x = 0$ tot $x = p$ wentelt om de $x$-as. Bereken exact de waarde van $p$ waarvoor de inhoud van $L_p$ gelijk is aan $9\pi$.$h15sql$, 2, $h15sql$Een primitieve van $x^{2}$ is $\dfrac{1}{3}x^{3}$. Dus $I(L_p) = \pi \cdot \dfrac{1}{3}p^{3}$.$h15sql$),
  ('h15c_vergelijk', 'h15c_vergelijk', $h15sql$Voor elke $p > 0$ ontstaat het lichaam $L_p$ als het vlakdeel onder $y = x$ van $x = 0$ tot $x = p$ wentelt om de $x$-as. Bereken exact de waarde van $p$ waarvoor de inhoud van $L_p$ gelijk is aan $9\pi$.$h15sql$, 3, $h15sql$Deel 3: $\dfrac{1}{3}p^{3} = 9$, dus $p^{3} = 27$ en $p = 3$.$h15sql$),
  ('h15c_vergelijk', 'h15c_vergelijk', $h15sql$Voor elke $p > 0$ ontstaat het lichaam $L_p$ als het vlakdeel onder $y = \sqrt{x}$ van $x = 0$ tot $x = p$ wentelt om de $x$-as. Bereken exact de waarde van $p$ waarvoor de inhoud van $L_p$ gelijk is aan $8\pi$.$h15sql$, 0, $h15sql$Hier spelen alle drie de delen: het verhaal wordt een integraal, die reken je exact uit, en met die uitkomst vind je de gevraagde waarde.$h15sql$),
  ('h15c_vergelijk', 'h15c_vergelijk', $h15sql$Voor elke $p > 0$ ontstaat het lichaam $L_p$ als het vlakdeel onder $y = \sqrt{x}$ van $x = 0$ tot $x = p$ wentelt om de $x$-as. Bereken exact de waarde van $p$ waarvoor de inhoud van $L_p$ gelijk is aan $8\pi$.$h15sql$, 1, $h15sql$$I(L_p) = \pi \displaystyle\int_{0}^{p} x\,\mathrm{d}x$, want $\left(\sqrt{x}\right)^{2} = x$.$h15sql$),
  ('h15c_vergelijk', 'h15c_vergelijk', $h15sql$Voor elke $p > 0$ ontstaat het lichaam $L_p$ als het vlakdeel onder $y = \sqrt{x}$ van $x = 0$ tot $x = p$ wentelt om de $x$-as. Bereken exact de waarde van $p$ waarvoor de inhoud van $L_p$ gelijk is aan $8\pi$.$h15sql$, 2, $h15sql$Een primitieve van $x$ is $\dfrac{1}{2}x^{2}$. Dus $I(L_p) = \pi \cdot \dfrac{1}{2}p^{2}$.$h15sql$),
  ('h15c_vergelijk', 'h15c_vergelijk', $h15sql$Voor elke $p > 0$ ontstaat het lichaam $L_p$ als het vlakdeel onder $y = \sqrt{x}$ van $x = 0$ tot $x = p$ wentelt om de $x$-as. Bereken exact de waarde van $p$ waarvoor de inhoud van $L_p$ gelijk is aan $8\pi$.$h15sql$, 3, $h15sql$Deel 3: $\dfrac{1}{2}p^{2} = 8$, dus $p^{2} = 16$ en $p = 4$.$h15sql$),
  ('h15c_vergelijk', 'h15c_vergelijk', $h15sql$Voor elke $a > 0$ wordt het vlakdeel onder $y = x^{2}$ van $x = 0$ tot $x = a$ bekeken. Lichaam $L$ ontstaat bij wentelen om de $x$-as, lichaam $M$ bij wentelen om de $y$-as. Bereken exact de waarde van $a$ waarvoor de inhoud van $L$ gelijk is aan de inhoud van $M$.$h15sql$, 0, $h15sql$Hier spelen alle drie de delen: het verhaal wordt een integraal, die reken je exact uit, en met die uitkomst vind je de gevraagde waarde.$h15sql$),
  ('h15c_vergelijk', 'h15c_vergelijk', $h15sql$Voor elke $a > 0$ wordt het vlakdeel onder $y = x^{2}$ van $x = 0$ tot $x = a$ bekeken. Lichaam $L$ ontstaat bij wentelen om de $x$-as, lichaam $M$ bij wentelen om de $y$-as. Bereken exact de waarde van $a$ waarvoor de inhoud van $L$ gelijk is aan de inhoud van $M$.$h15sql$, 1, $h15sql$$I(L) = \pi \displaystyle\int_{0}^{a} x^{4}\,\mathrm{d}x = \pi \cdot \dfrac{1}{5}a^{5}$. Voor $M$ geldt $x = \sqrt{y}$ en $y$ loopt van $0$ tot $a^{2}$, dus $I(M) = \pi \displaystyle\int_{0}^{a^{2}} y\,\mathrm{d}y = \pi \cdot \dfrac{1}{2}a^{4}$.$h15sql$),
  ('h15c_vergelijk', 'h15c_vergelijk', $h15sql$Voor elke $a > 0$ wordt het vlakdeel onder $y = x^{2}$ van $x = 0$ tot $x = a$ bekeken. Lichaam $L$ ontstaat bij wentelen om de $x$-as, lichaam $M$ bij wentelen om de $y$-as. Bereken exact de waarde van $a$ waarvoor de inhoud van $L$ gelijk is aan de inhoud van $M$.$h15sql$, 2, $h15sql$Stel $I(L) = I(M)$: $\dfrac{1}{5}a^{5} = \dfrac{1}{2}a^{4}$. Deel door $a^{4}$, dat mag omdat $a > 0$: $\dfrac{1}{5}a = \dfrac{1}{2}$.$h15sql$),
  ('h15c_vergelijk', 'h15c_vergelijk', $h15sql$Voor elke $a > 0$ wordt het vlakdeel onder $y = x^{2}$ van $x = 0$ tot $x = a$ bekeken. Lichaam $L$ ontstaat bij wentelen om de $x$-as, lichaam $M$ bij wentelen om de $y$-as. Bereken exact de waarde van $a$ waarvoor de inhoud van $L$ gelijk is aan de inhoud van $M$.$h15sql$, 3, $h15sql$Deel 3: $a = \dfrac{5}{2}$.$h15sql$),
  ('h15c_vergelijk', 'h15c_vergelijk', $h15sql$Voor elke $k > 0$ ontstaat het lichaam $L_k$ als de rechthoek onder $y = k$ van $x = 0$ tot $x = 2$ wentelt om de $x$-as. Bereken exact de waarde van $k$ waarvoor de inhoud van $L_k$ gelijk is aan $18\pi$.$h15sql$, 0, $h15sql$Hier spelen alle drie de delen: het verhaal wordt een integraal, die reken je exact uit, en met die uitkomst vind je de gevraagde waarde.$h15sql$),
  ('h15c_vergelijk', 'h15c_vergelijk', $h15sql$Voor elke $k > 0$ ontstaat het lichaam $L_k$ als de rechthoek onder $y = k$ van $x = 0$ tot $x = 2$ wentelt om de $x$-as. Bereken exact de waarde van $k$ waarvoor de inhoud van $L_k$ gelijk is aan $18\pi$.$h15sql$, 1, $h15sql$$I(L_k) = \pi \displaystyle\int_{0}^{2} k^{2}\,\mathrm{d}x = 2\pi k^{2}$.$h15sql$),
  ('h15c_vergelijk', 'h15c_vergelijk', $h15sql$Voor elke $k > 0$ ontstaat het lichaam $L_k$ als de rechthoek onder $y = k$ van $x = 0$ tot $x = 2$ wentelt om de $x$-as. Bereken exact de waarde van $k$ waarvoor de inhoud van $L_k$ gelijk is aan $18\pi$.$h15sql$, 2, $h15sql$De vergelijking is $2k^{2} = 18$, dus $k^{2} = 9$.$h15sql$),
  ('h15c_vergelijk', 'h15c_vergelijk', $h15sql$Voor elke $k > 0$ ontstaat het lichaam $L_k$ als de rechthoek onder $y = k$ van $x = 0$ tot $x = 2$ wentelt om de $x$-as. Bereken exact de waarde van $k$ waarvoor de inhoud van $L_k$ gelijk is aan $18\pi$.$h15sql$, 3, $h15sql$Deel 3: $k > 0$, dus $k = 3$.$h15sql$),
  ('h15c_vergelijk', 'h15c_vergelijk', $h15sql$Voor elke $p > 0$ ontstaat het lichaam $L_p$ als het vlakdeel onder $y = \sqrt{x}$ van $x = 0$ tot $x = p$ wentelt om de $y$-as. Bereken exact de waarde van $p$ waarvoor de inhoud van $L_p$ gelijk is aan $\dfrac{32}{5}\pi$.$h15sql$, 0, $h15sql$Hier spelen alle drie de delen: het verhaal wordt een integraal, die reken je exact uit, en met die uitkomst vind je de gevraagde waarde.$h15sql$),
  ('h15c_vergelijk', 'h15c_vergelijk', $h15sql$Voor elke $p > 0$ ontstaat het lichaam $L_p$ als het vlakdeel onder $y = \sqrt{x}$ van $x = 0$ tot $x = p$ wentelt om de $y$-as. Bereken exact de waarde van $p$ waarvoor de inhoud van $L_p$ gelijk is aan $\dfrac{32}{5}\pi$.$h15sql$, 1, $h15sql$$y$ loopt van $0$ tot $\sqrt{p}$ en de straal is $x = y^{2}$. $I(L_p) = \pi \displaystyle\int_{0}^{\sqrt{p}} y^{4}\,\mathrm{d}y = \pi \cdot \dfrac{1}{5}p^{5/2}$.$h15sql$),
  ('h15c_vergelijk', 'h15c_vergelijk', $h15sql$Voor elke $p > 0$ ontstaat het lichaam $L_p$ als het vlakdeel onder $y = \sqrt{x}$ van $x = 0$ tot $x = p$ wentelt om de $y$-as. Bereken exact de waarde van $p$ waarvoor de inhoud van $L_p$ gelijk is aan $\dfrac{32}{5}\pi$.$h15sql$, 2, $h15sql$Stel $\dfrac{1}{5}p^{5/2} = \dfrac{32}{5}$. Dan $p^{5/2} = 32 = 2^{5}$.$h15sql$),
  ('h15c_vergelijk', 'h15c_vergelijk', $h15sql$Voor elke $p > 0$ ontstaat het lichaam $L_p$ als het vlakdeel onder $y = \sqrt{x}$ van $x = 0$ tot $x = p$ wentelt om de $y$-as. Bereken exact de waarde van $p$ waarvoor de inhoud van $L_p$ gelijk is aan $\dfrac{32}{5}\pi$.$h15sql$, 3, $h15sql$Deel 3: $\sqrt{p} = 2$, dus $p = 4$.$h15sql$),
  ('h15c_vergelijk', 'h15c_vergelijk', $h15sql$Lichaam $L$ ontstaat als het vlakdeel onder $y = x$ van $x = 0$ tot $x = 2$ wentelt om de $x$-as. Lichaam $M_p$ ontstaat op dezelfde manier, maar tot $x = p$ met $p > 0$. Bereken exact de waarde van $p$ waarvoor de inhoud van $M_p$ twee keer zo groot is als de inhoud van $L$.$h15sql$, 0, $h15sql$Hier spelen alle drie de delen: het verhaal wordt een integraal, die reken je exact uit, en met die uitkomst vind je de gevraagde waarde.$h15sql$),
  ('h15c_vergelijk', 'h15c_vergelijk', $h15sql$Lichaam $L$ ontstaat als het vlakdeel onder $y = x$ van $x = 0$ tot $x = 2$ wentelt om de $x$-as. Lichaam $M_p$ ontstaat op dezelfde manier, maar tot $x = p$ met $p > 0$. Bereken exact de waarde van $p$ waarvoor de inhoud van $M_p$ twee keer zo groot is als de inhoud van $L$.$h15sql$, 1, $h15sql$$I(L) = \pi \displaystyle\int_{0}^{2} x^{2}\,\mathrm{d}x = \pi \cdot \dfrac{8}{3}$. En $I(M_p) = \pi \cdot \dfrac{1}{3}p^{3}$.$h15sql$),
  ('h15c_vergelijk', 'h15c_vergelijk', $h15sql$Lichaam $L$ ontstaat als het vlakdeel onder $y = x$ van $x = 0$ tot $x = 2$ wentelt om de $x$-as. Lichaam $M_p$ ontstaat op dezelfde manier, maar tot $x = p$ met $p > 0$. Bereken exact de waarde van $p$ waarvoor de inhoud van $M_p$ twee keer zo groot is als de inhoud van $L$.$h15sql$, 2, $h15sql$Twee keer de inhoud van $L$ is $\dfrac{16}{3}\pi$. Dus $\dfrac{1}{3}p^{3} = \dfrac{16}{3}$.$h15sql$),
  ('h15c_vergelijk', 'h15c_vergelijk', $h15sql$Lichaam $L$ ontstaat als het vlakdeel onder $y = x$ van $x = 0$ tot $x = 2$ wentelt om de $x$-as. Lichaam $M_p$ ontstaat op dezelfde manier, maar tot $x = p$ met $p > 0$. Bereken exact de waarde van $p$ waarvoor de inhoud van $M_p$ twee keer zo groot is als de inhoud van $L$.$h15sql$, 3, $h15sql$Deel 3: $p^{3} = 16$, dus $p = \sqrt[3]{16}$.$h15sql$),
  ('h15c_vergelijk', 'h15c_vergelijk', $h15sql$Voor elke $a > 0$ wordt het vlakdeel onder $y = \sqrt{x}$ van $x = 0$ tot $x = a$ bekeken. Lichaam $L$ ontstaat bij wentelen om de $x$-as, lichaam $M$ bij wentelen om de $y$-as. Bereken exact de waarde van $a$ waarvoor de inhoud van $L$ gelijk is aan de inhoud van $M$.$h15sql$, 0, $h15sql$Hier spelen alle drie de delen: het verhaal wordt een integraal, die reken je exact uit, en met die uitkomst vind je de gevraagde waarde.$h15sql$),
  ('h15c_vergelijk', 'h15c_vergelijk', $h15sql$Voor elke $a > 0$ wordt het vlakdeel onder $y = \sqrt{x}$ van $x = 0$ tot $x = a$ bekeken. Lichaam $L$ ontstaat bij wentelen om de $x$-as, lichaam $M$ bij wentelen om de $y$-as. Bereken exact de waarde van $a$ waarvoor de inhoud van $L$ gelijk is aan de inhoud van $M$.$h15sql$, 1, $h15sql$$I(L) = \pi \displaystyle\int_{0}^{a} x\,\mathrm{d}x = \pi \cdot \dfrac{1}{2}a^{2}$. Voor $M$ loopt $y$ van $0$ tot $\sqrt{a}$ en is de straal $y^{2}$, dus $I(M) = \pi \displaystyle\int_{0}^{\sqrt{a}} y^{4}\,\mathrm{d}y = \pi \cdot \dfrac{1}{5}a^{5/2}$.$h15sql$),
  ('h15c_vergelijk', 'h15c_vergelijk', $h15sql$Voor elke $a > 0$ wordt het vlakdeel onder $y = \sqrt{x}$ van $x = 0$ tot $x = a$ bekeken. Lichaam $L$ ontstaat bij wentelen om de $x$-as, lichaam $M$ bij wentelen om de $y$-as. Bereken exact de waarde van $a$ waarvoor de inhoud van $L$ gelijk is aan de inhoud van $M$.$h15sql$, 2, $h15sql$Stel $\dfrac{1}{2}a^{2} = \dfrac{1}{5}a^{5/2}$. Deel door $a^{2}$, dat mag omdat $a > 0$: $\dfrac{1}{2} = \dfrac{1}{5}\sqrt{a}$.$h15sql$),
  ('h15c_vergelijk', 'h15c_vergelijk', $h15sql$Voor elke $a > 0$ wordt het vlakdeel onder $y = \sqrt{x}$ van $x = 0$ tot $x = a$ bekeken. Lichaam $L$ ontstaat bij wentelen om de $x$-as, lichaam $M$ bij wentelen om de $y$-as. Bereken exact de waarde van $a$ waarvoor de inhoud van $L$ gelijk is aan de inhoud van $M$.$h15sql$, 3, $h15sql$Deel 3: $\sqrt{a} = \dfrac{5}{2}$, dus $a = \dfrac{25}{4}$.$h15sql$),
  ('h15c_vergelijk', 'h15c_vergelijk', $h15sql$Lichaam $L$ ontstaat als het vlakdeel tussen $y = 2$ en $y = x$ op $[0, 2]$ wentelt om de $x$-as. Voor elke $q > 0$ ontstaat lichaam $M_q$ als de rechthoek onder $y = q$ van $x = 0$ tot $x = 3$ wentelt om de $x$-as. Bereken exact de waarde van $q$ waarvoor de inhoud van $M_q$ gelijk is aan de inhoud van $L$.$h15sql$, 0, $h15sql$Hier spelen alle drie de delen: het verhaal wordt een integraal, die reken je exact uit, en met die uitkomst vind je de gevraagde waarde.$h15sql$),
  ('h15c_vergelijk', 'h15c_vergelijk', $h15sql$Lichaam $L$ ontstaat als het vlakdeel tussen $y = 2$ en $y = x$ op $[0, 2]$ wentelt om de $x$-as. Voor elke $q > 0$ ontstaat lichaam $M_q$ als de rechthoek onder $y = q$ van $x = 0$ tot $x = 3$ wentelt om de $x$-as. Bereken exact de waarde van $q$ waarvoor de inhoud van $M_q$ gelijk is aan de inhoud van $L$.$h15sql$, 1, $h15sql$$I(L) = \pi \displaystyle\int_{0}^{2} (4 - x^{2})\,\mathrm{d}x = \pi\left[4x - \dfrac{1}{3}x^{3}\right]_{0}^{2} = \dfrac{16}{3}\pi$. En $I(M_q) = \pi \displaystyle\int_{0}^{3} q^{2}\,\mathrm{d}x = 3\pi q^{2}$.$h15sql$),
  ('h15c_vergelijk', 'h15c_vergelijk', $h15sql$Lichaam $L$ ontstaat als het vlakdeel tussen $y = 2$ en $y = x$ op $[0, 2]$ wentelt om de $x$-as. Voor elke $q > 0$ ontstaat lichaam $M_q$ als de rechthoek onder $y = q$ van $x = 0$ tot $x = 3$ wentelt om de $x$-as. Bereken exact de waarde van $q$ waarvoor de inhoud van $M_q$ gelijk is aan de inhoud van $L$.$h15sql$, 2, $h15sql$Stel $3q^{2} = \dfrac{16}{3}$. Dan $q^{2} = \dfrac{16}{9}$.$h15sql$),
  ('h15c_vergelijk', 'h15c_vergelijk', $h15sql$Lichaam $L$ ontstaat als het vlakdeel tussen $y = 2$ en $y = x$ op $[0, 2]$ wentelt om de $x$-as. Voor elke $q > 0$ ontstaat lichaam $M_q$ als de rechthoek onder $y = q$ van $x = 0$ tot $x = 3$ wentelt om de $x$-as. Bereken exact de waarde van $q$ waarvoor de inhoud van $M_q$ gelijk is aan de inhoud van $L$.$h15sql$, 3, $h15sql$Deel 3: $q > 0$, dus $q = \dfrac{4}{3}$.$h15sql$)
) AS v(topic_slug, cluster_slug, latex_body, step_order, step_description)
JOIN public.topics_new t ON t.slug = v.topic_slug AND t.site = 'integralen'
JOIN public.topic_clusters_new cl ON cl.slug = v.cluster_slug AND cl.topic_id = t.id
JOIN public.questions_new vr ON vr.latex_body = v.latex_body AND vr.cluster_id = cl.id
ON CONFLICT (question_id, step_order) DO NOTHING;

-- 6. Topics aan het theorieblok koppelen
-- Alleen de topics van dit blok, en alleen als de koppeling er nog niet staat.
UPDATE public.topics_new AS t
SET theory_block_id = b.id
FROM (VALUES
  ('h15a_primitiveren', 'h15a'),
  ('h15a_bepaald', 'h15a'),
  ('h15a_oppervlakte', 'h15a')
) AS v(topic_slug, block_slug)
JOIN public.theory_blocks b ON b.slug = v.block_slug AND b.site = 'integralen'
WHERE t.slug = v.topic_slug
  AND t.site = 'integralen'
  AND t.theory_block_id IS DISTINCT FROM b.id;

DO $blok$
DECLARE n int;
BEGIN
  SELECT count(*) INTO n
  FROM public.topics_new t
  JOIN public.theory_blocks b ON b.id = t.theory_block_id
  WHERE t.site = 'integralen'
    AND b.slug = 'h15a'
    AND t.slug IN ('h15a_primitiveren', 'h15a_bepaald', 'h15a_oppervlakte');
  IF n <> 3 THEN
    RAISE EXCEPTION 'Theorieblok h15a hoort 3 topics te hebben, gevonden %', n;
  END IF;
END $blok$;

-- 6b. Topics van theorieblok B en C koppelen
UPDATE public.topics_new AS t
SET theory_block_id = b.id
FROM (VALUES
  ('h15b_verhouding', 'h15b'),
  ('h15b_parameter', 'h15b'),
  ('h15c_xas', 'h15c'),
  ('h15c_yas', 'h15c'),
  ('h15c_vergelijk', 'h15c')
) AS v(topic_slug, block_slug)
JOIN public.theory_blocks b ON b.slug = v.block_slug AND b.site = 'integralen'
WHERE t.slug = v.topic_slug
  AND t.site = 'integralen'
  AND t.theory_block_id IS DISTINCT FROM b.id;

DO $blokbc$
DECLARE n int;
BEGIN
  SELECT count(*) INTO n
  FROM public.topics_new t
  JOIN public.theory_blocks b ON b.id = t.theory_block_id
  WHERE t.site = 'integralen'
    AND b.slug = 'h15b'
    AND t.slug IN ('h15b_verhouding', 'h15b_parameter');
  IF n <> 2 THEN
    RAISE EXCEPTION 'Theorieblok h15b hoort 2 topics te hebben, gevonden %', n;
  END IF;
  SELECT count(*) INTO n
  FROM public.topics_new t
  JOIN public.theory_blocks b ON b.id = t.theory_block_id
  WHERE t.site = 'integralen'
    AND b.slug = 'h15c'
    AND t.slug IN ('h15c_xas', 'h15c_yas', 'h15c_vergelijk');
  IF n <> 3 THEN
    RAISE EXCEPTION 'Theorieblok h15c hoort 3 topics te hebben, gevonden %', n;
  END IF;
END $blokbc$;

-- 7. Controle
DO $do$
DECLARE n int;
BEGIN
  SELECT count(*) INTO n FROM public.questions_new WHERE cluster_id = (SELECT id FROM public.topic_clusters_new WHERE slug = 'h15a_primitief' AND topic_id = (SELECT id FROM public.topics_new WHERE slug = 'h15a_primitiveren' AND site = 'integralen'));
  IF n <> 8 THEN RAISE EXCEPTION 'Cluster h15a_primitief hoort 8 vragen te hebben, gevonden %', n; END IF;
  SELECT count(*) INTO n FROM public.questions_new WHERE cluster_id = (SELECT id FROM public.topic_clusters_new WHERE slug = 'h15a_bepaald' AND topic_id = (SELECT id FROM public.topics_new WHERE slug = 'h15a_bepaald' AND site = 'integralen'));
  IF n <> 8 THEN RAISE EXCEPTION 'Cluster h15a_bepaald hoort 8 vragen te hebben, gevonden %', n; END IF;
  SELECT count(*) INTO n FROM public.questions_new WHERE cluster_id = (SELECT id FROM public.topic_clusters_new WHERE slug = 'h15a_oppervlakte' AND topic_id = (SELECT id FROM public.topics_new WHERE slug = 'h15a_oppervlakte' AND site = 'integralen'));
  IF n <> 8 THEN RAISE EXCEPTION 'Cluster h15a_oppervlakte hoort 8 vragen te hebben, gevonden %', n; END IF;
  SELECT count(*) INTO n FROM public.questions_new WHERE cluster_id = (SELECT id FROM public.topic_clusters_new WHERE slug = 'h15b_verhouding' AND topic_id = (SELECT id FROM public.topics_new WHERE slug = 'h15b_verhouding' AND site = 'integralen'));
  IF n <> 8 THEN RAISE EXCEPTION 'Cluster h15b_verhouding hoort 8 vragen te hebben, gevonden %', n; END IF;
  SELECT count(*) INTO n FROM public.questions_new WHERE cluster_id = (SELECT id FROM public.topic_clusters_new WHERE slug = 'h15b_parameter' AND topic_id = (SELECT id FROM public.topics_new WHERE slug = 'h15b_parameter' AND site = 'integralen'));
  IF n <> 8 THEN RAISE EXCEPTION 'Cluster h15b_parameter hoort 8 vragen te hebben, gevonden %', n; END IF;
  SELECT count(*) INTO n FROM public.questions_new WHERE cluster_id = (SELECT id FROM public.topic_clusters_new WHERE slug = 'h15c_xas' AND topic_id = (SELECT id FROM public.topics_new WHERE slug = 'h15c_xas' AND site = 'integralen'));
  IF n <> 8 THEN RAISE EXCEPTION 'Cluster h15c_xas hoort 8 vragen te hebben, gevonden %', n; END IF;
  SELECT count(*) INTO n FROM public.questions_new WHERE cluster_id = (SELECT id FROM public.topic_clusters_new WHERE slug = 'h15c_yas' AND topic_id = (SELECT id FROM public.topics_new WHERE slug = 'h15c_yas' AND site = 'integralen'));
  IF n <> 8 THEN RAISE EXCEPTION 'Cluster h15c_yas hoort 8 vragen te hebben, gevonden %', n; END IF;
  SELECT count(*) INTO n FROM public.questions_new WHERE cluster_id = (SELECT id FROM public.topic_clusters_new WHERE slug = 'h15c_vergelijk' AND topic_id = (SELECT id FROM public.topics_new WHERE slug = 'h15c_vergelijk' AND site = 'integralen'));
  IF n <> 8 THEN RAISE EXCEPTION 'Cluster h15c_vergelijk hoort 8 vragen te hebben, gevonden %', n; END IF;
  SELECT count(*) INTO n FROM public.question_steps_new s
  JOIN public.questions_new vr ON vr.id = s.question_id
  JOIN public.topics_new t ON t.id = vr.topic_id
  WHERE t.site = 'integralen' AND t.slug IN ('h15a_primitiveren', 'h15a_bepaald', 'h15a_oppervlakte', 'h15b_verhouding', 'h15b_parameter', 'h15c_xas', 'h15c_yas', 'h15c_vergelijk');
  IF n <> 256 THEN RAISE EXCEPTION 'Deze topics horen samen 256 stappen te hebben, gevonden %', n; END IF;
END $do$;

COMMIT;
